export default AdminChallengeViewPage;

import { connectToDatabase } from "@/database/mongoose";
import { formatVolts } from "@/lib/utils/format-volts";
import NotificationTemplate, {
  NotificationType,
  NotificationCategory,
} from "@/database/models/notification-template.model";
import Notification, {
  INotification,
} from "@/database/models/notification.model";
import UserNotificationPreferences from "@/database/models/user-notification-preferences.model";

interface SendNotificationParams {
  userId: string;
  templateId: string;
  variables?: Record<string, string | number>;
  metadata?: Record<string, any>;
  overrideTitle?: string;
  overrideMessage?: string;
}

interface SendInstantNotificationParams {
  userId: string | "all";
  title: string;
  message: string;
  category?: NotificationCategory;
  priority?: "low" | "normal" | "high" | "urgent";
  icon?: string;
  color?: string;
  actionUrl?: string;
  actionText?: string;
  expiresAt?: Date;
  sentBy?: {
    adminId: string;
    adminEmail: string;
  };
}

interface SendBulkNotificationParams {
  userIds: string[];
  templateId: string;
  variables?: Record<string, string | number>;
  metadata?: Record<string, any>;
}

class NotificationService {
  private static templatesSeeded = false;

  /**
   * Ensure templates are seeded
   */
  private async ensureTemplatesSeeded(): Promise<void> {
    if (NotificationService.templatesSeeded) return;

    const count = await NotificationTemplate.countDocuments();
    if (count === 0) {
      console.log("≡ƒôï No notification templates found, seeding defaults...");
      await NotificationTemplate.seedDefaults();
    }
    NotificationService.templatesSeeded = true;
  }

  /**
   * Send a notification using a template
   */
  async send(params: SendNotificationParams): Promise<INotification | null> {
    await connectToDatabase();

    // Ensure templates are seeded
    await this.ensureTemplatesSeeded();

    let template = await NotificationTemplate.findOne({
      templateId: params.templateId,
      isEnabled: true,
    });

    // If template not found, try seeding again (might be first run)
    if (!template) {
      console.log(
        `ΓÜá∩╕Å Template "${params.templateId}" not found, attempting to seed...`,
      );
      await NotificationTemplate.seedDefaults();
      template = await NotificationTemplate.findOne({
        templateId: params.templateId,
        isEnabled: true,
      });
    }

    if (!template) {
      console.log(
        `Γ¥î Notification template "${params.templateId}" not found or disabled after seeding`,
      );
      return null;
    }

    // Check if user wants to receive this notification
    console.log(
      `≡ƒöì Checking if notification "${params.templateId}" is enabled for user ${params.userId}`,
    );
    let isEnabled = true;
    try {
      isEnabled = await UserNotificationPreferences.isNotificationEnabled(
        params.userId,
        template.category as NotificationCategory,
        params.templateId,
      );
      console.log(
        `   User preference check result: ${isEnabled ? "enabled" : "disabled"}`,
      );
    } catch (error) {
      console.log(
        `   ΓÜá∩╕Å Error checking preferences, defaulting to enabled:`,
        error,
      );
      isEnabled = true; // Default to enabled on error
    }

    if (!isEnabled) {
      console.log(
        `≡ƒöò Notification "${params.templateId}" disabled by user ${params.userId}`,
      );
      return null;
    }

    // Replace variables in title and message
    let title = params.overrideTitle || template.title;
    let message = params.overrideMessage || template.message;

    if (params.variables) {
      for (const [key, value] of Object.entries(params.variables)) {
        const regex = new RegExp(`{{${key}}}`, "g");
        title = title.replace(regex, String(value));
        message = message.replace(regex, String(value));
      }
    }

    // Also replace variables in actionUrl if present
    let actionUrl = template.actionUrl;
    if (actionUrl && params.variables) {
      for (const [key, value] of Object.entries(params.variables)) {
        const regex = new RegExp(`{{${key}}}`, "g");
        actionUrl = actionUrl.replace(regex, String(value));
      }
    }

    console.log(`≡ƒô¥ Creating notification in database...`);
    console.log(`   User: ${params.userId}`);
    console.log(`   Template: ${params.templateId}`);
    console.log(`   Title: ${title}`);

    const notification = await Notification.create({
      userId: params.userId,
      templateId: params.templateId,
      title,
      message,
      icon: template.icon,
      category: template.category,
      type: template.type,
      priority: template.priority,
      color: template.color,
      actionUrl,
      actionText: template.actionText,
      metadata: params.metadata || {},
      isInstant: false,
    });

    console.log(`Γ£à Notification created with ID: ${notification._id}`);
    console.log(
      `≡ƒô¼ Notification sent: [${template.type}] to user ${params.userId}`,
    );

    return notification;
  }

  /**
   * Send an instant/custom notification (not from template)
   */
  async sendInstant(
    params: SendInstantNotificationParams,
  ): Promise<INotification | INotification[]> {
    await connectToDatabase();

    const notificationData = {
      templateId: "instant",
      title: params.title,
      message: params.message,
      icon: params.icon || "≡ƒôó",
      category: params.category || ("admin" as NotificationCategory),
      type: "admin_message" as NotificationType,
      priority: params.priority || "normal",
      color: params.color || "#FDD458",
      actionUrl: params.actionUrl,
      actionText: params.actionText,
      sentBy: params.sentBy,
      isInstant: true,
      expiresAt: params.expiresAt,
    };

    if (params.userId === "all") {
      // Send to all users - get all unique userIds from better-auth user collection
      const mongoose = await connectToDatabase();
      const db = mongoose.connection.db;

      if (!db) {
        throw new Error("Database connection not found");
      }

      // better-auth stores users in 'user' collection with 'id' field
      const users = await db
        .collection("user")
        .find({})
        .project({ id: 1, _id: 1 })
        .toArray();

      const notifications = await Notification.insertMany(
        users.map((user) => ({
          ...notificationData,
          userId: user.id || user._id?.toString(),
        })),
      );

      console.log(`≡ƒôó Broadcast notification sent to ${users.length} users`);
      return notifications;
    }

    const notification = await Notification.create({
      ...notificationData,
      userId: params.userId,
    });

    console.log(`≡ƒô¼ Instant notification sent to user ${params.userId}`);
    return notification;
  }

  /**
   * Create a custom notification directly (without template)
   * Compatible with main app's notification service
   */
  async createCustom(data: {
    userId: string;
    type: string;
    title: string;
    message: string;
    icon?: string;
    category?: string;
    priority?: string;
    color?: string;
    actionUrl?: string;
    actionText?: string;
    metadata?: Record<string, unknown>;
  }): Promise<INotification | null> {
    try {
      await connectToDatabase();

      const notification = await Notification.create({
        userId: data.userId,
        templateId: `custom_${data.type}`,
        title: data.title,
        message: data.message,
        icon: data.icon || "bell",
        category: data.category || "system",
        type: data.type,
        priority: data.priority || "normal",
        color: data.color || "blue",
        actionUrl: data.actionUrl,
        actionText: data.actionText,
        isRead: false,
        metadata: data.metadata || {},
        isInstant: true,
      });

      console.log(`≡ƒô¼ Custom notification created for user ${data.userId}`);
      return notification;
    } catch (error) {
      console.error("Error creating custom notification:", error);
      return null;
    }
  }

  /**
   * Send notification to multiple users
   */
  async sendBulk(params: SendBulkNotificationParams): Promise<number> {
    await connectToDatabase();

    const template = await NotificationTemplate.findOne({
      templateId: params.templateId,
      isEnabled: true,
    });

    if (!template) {
      console.log(
        `ΓÜá∩╕Å Notification template "${params.templateId}" not found or disabled`,
      );
      return 0;
    }

    // Replace variables in title and message
    let title = template.title;
    let message = template.message;

    if (params.variables) {
      for (const [key, value] of Object.entries(params.variables)) {
        const regex = new RegExp(`{{${key}}}`, "g");
        title = title.replace(regex, String(value));
        message = message.replace(regex, String(value));
      }
    }

    let actionUrl = template.actionUrl;
    if (actionUrl && params.variables) {
      for (const [key, value] of Object.entries(params.variables)) {
        const regex = new RegExp(`{{${key}}}`, "g");
        actionUrl = actionUrl.replace(regex, String(value));
      }
    }

    const notifications = await Notification.insertMany(
      params.userIds.map((userId) => ({
        userId,
        templateId: params.templateId,
        title,
        message,
        icon: template.icon,
        category: template.category,
        type: template.type,
        priority: template.priority,
        color: template.color,
        actionUrl,
        actionText: template.actionText,
        metadata: params.metadata || {},
        isInstant: false,
      })),
    );

    console.log(`≡ƒô¼ Bulk notification sent to ${notifications.length} users`);
    return notifications.length;
  }

