  // ========== QUERY METHODS ==========

  async getUserNotifications(
    userId: string,
    options: {
      limit?: number;
      offset?: number;
      category?: NotificationCategory;
      unreadOnly?: boolean;
    } = {},
  ) {
    await connectToDatabase();

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const query: any = { userId };

    if (options.category) {
      query.category = options.category;
    }

    if (options.unreadOnly) {
      query.isRead = false;
    }

    const notifications = await Notification.find(query)
      .sort({ createdAt: -1 })
      .skip(options.offset || 0)
      .limit(options.limit || 50)
      .lean();

    return notifications;
  }

  async getUnreadCount(userId: string): Promise<number> {
    await connectToDatabase();
    return Notification.countDocuments({ userId, isRead: false });
  }

  async markAsRead(notificationId: string, userId: string): Promise<boolean> {
    await connectToDatabase();

    const result = await Notification.updateOne(
      { _id: notificationId, userId },
      { $set: { isRead: true, readAt: new Date() } },
    );

    return result.modifiedCount > 0;
  }

  async markAllAsRead(userId: string): Promise<number> {
    await connectToDatabase();

    const result = await Notification.updateMany(
      { userId, isRead: false },
      { $set: { isRead: true, readAt: new Date() } },
    );

    return result.modifiedCount;
  }

  async deleteNotification(
    notificationId: string,
    userId: string,
  ): Promise<boolean> {
    await connectToDatabase();

    const result = await Notification.deleteOne({
      _id: notificationId,
      userId,
    });
    return result.deletedCount > 0;
  }

  async clearAllNotifications(userId: string): Promise<number> {
    await connectToDatabase();

    const result = await Notification.deleteMany({ userId });
    return result.deletedCount;
  }

  // ========== ADMIN METHODS ==========

  async seedDefaultTemplates(): Promise<void> {
    await connectToDatabase();
    await NotificationTemplate.seedDefaults();
  }

  async getTemplates(category?: NotificationCategory) {
    await connectToDatabase();

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const query: any = {};
    if (category) {
      query.category = category;
    }

    return NotificationTemplate.find(query)
      .sort({ category: 1, name: 1 })
      .lean();
  }

  async updateTemplate(
    templateId: string,
    updates: Partial<{
      name: string;
      title: string;
      message: string;
      icon: string;
      priority: string;
      color: string;
      isEnabled: boolean;
      actionUrl: string;
      actionText: string;
      channels: { inApp: boolean; email: boolean; push: boolean };
    }>,
  ) {
    await connectToDatabase();

    return NotificationTemplate.findOneAndUpdate(
      { templateId },
      { $set: updates },
      { new: true },
    );
  }

  async toggleTemplate(templateId: string, isEnabled: boolean) {
    await connectToDatabase();

    return NotificationTemplate.findOneAndUpdate(
      { templateId },
      { $set: { isEnabled } },
      { new: true },
    );
  }

  async toggleAllTemplates(isEnabled: boolean) {
    await connectToDatabase();

    return NotificationTemplate.updateMany({}, { $set: { isEnabled } });
  }

  async createCustomTemplate(data: {
    templateId: string;
    name: string;
    description?: string;
    category: NotificationCategory;
    title: string;
    message: string;
    icon?: string;
    priority?: "low" | "normal" | "high" | "urgent";
    color?: string;
    actionUrl?: string;
    actionText?: string;
  }) {
    await connectToDatabase();

    return NotificationTemplate.create({
      ...data,
      type: "custom",
      isEnabled: true,
      isDefault: false,
      isCustom: true,
      channels: { inApp: true, email: false, push: false },
    });
  }

  async deleteCustomTemplate(templateId: string): Promise<boolean> {
    await connectToDatabase();

    // Only allow deleting custom templates
    const result = await NotificationTemplate.deleteOne({
      templateId,
      isCustom: true,
    });

    return result.deletedCount > 0;
  }

  async getNotificationStats() {
    await connectToDatabase();

    const [totalSent, unreadCount, templateStats] = await Promise.all([
      Notification.countDocuments(),
      Notification.countDocuments({ isRead: false }),
      Notification.aggregate([
        { $group: { _id: "$category", count: { $sum: 1 } } },
        { $sort: { count: -1 } },
      ]),
    ]);

    return {
      totalSent,
      unreadCount,
      byCategory: templateStats.reduce(
        (acc, item) => {
          acc[item._id] = item.count;
          return acc;
        },
        {} as Record<string, number>,
      ),
    };
  }
}

