  userId: string;
  viewMode?: "card" | "list";
  onAccept?: (challengeId: string) => void;
  onDecline?: (challengeId: string) => void;
  responding?: boolean;
}

// Challenge themes based on ranking method
const CHALLENGE_THEMES: Record<
  string,
  { gradient: string; glow: string; icon: string; bgPattern: string }
> = {
  pnl: {
    gradient: "from-orange-600 via-red-500 to-pink-400",
    glow: "shadow-orange-500/50",
    icon: "ΓÜö∩╕Å",
    bgPattern:
      "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-orange-900/40 via-gray-900 to-gray-900",
  },
  roi: {
    gradient: "from-cyan-600 via-blue-500 to-indigo-400",
    glow: "shadow-cyan-500/50",
    icon: "≡ƒôê",
    bgPattern:
      "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-cyan-900/40 via-gray-900 to-gray-900",
  },
  total_capital: {
    gradient: "from-purple-600 via-violet-500 to-fuchsia-400",
    glow: "shadow-purple-500/50",
    icon: "≡ƒÆÄ",
    bgPattern:
      "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-purple-900/40 via-gray-900 to-gray-900",
  },
  win_rate: {
    gradient: "from-amber-600 via-yellow-500 to-orange-400",
    glow: "shadow-amber-500/50",
    icon: "≡ƒÄ»",
    bgPattern:
      "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-amber-900/40 via-gray-900 to-gray-900",
  },
  total_wins: {
    gradient: "from-red-600 via-rose-500 to-pink-400",
    glow: "shadow-red-500/50",
    icon: "≡ƒÅå",
    bgPattern:
      "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-red-900/40 via-gray-900 to-gray-900",
  },
  profit_factor: {
    gradient: "from-indigo-600 via-blue-500 to-cyan-400",
    glow: "shadow-indigo-500/50",
    icon: "ΓÜí",
    bgPattern:
      "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-indigo-900/40 via-gray-900 to-gray-900",
  },
};

const RANKING_DESCRIPTIONS: Record<
  string,
  { name: string; description: string }
> = {
  pnl: { name: "Profit & Loss", description: "Highest profit wins" },
  roi: { name: "Return on Investment", description: "Best % return wins" },
  total_capital: { name: "Total Capital", description: "Highest capital wins" },
  win_rate: { name: "Win Rate", description: "Best win % wins" },
  total_wins: { name: "Total Wins", description: "Most wins wins" },
  profit_factor: { name: "Profit Factor", description: "Best ratio wins" },
};

export default function ChallengeCard({
  challenge,
  userId,
  viewMode = "card",
  onAccept,
  onDecline,
  responding = false,
}: ChallengeCardProps) {
  const [liveCountdown, setLiveCountdown] = useState("");
  const { settings } = useAppSettings();

  const isChallenger = challenge.challengerId === userId;
  const opponentName = isChallenger
    ? challenge.challengedName
    : challenge.challengerName;
  const canRespond = !isChallenger && challenge.status === "pending";
  const isWinner = challenge.winnerId === userId;
  const isLoser = challenge.loserId === userId;
  const isNoWinner = challenge.noWinner === true; // Both disqualified - no winner
  const isActive = challenge.status === "active";
  const isPending = challenge.status === "pending";
  const isCompleted = challenge.status === "completed";
  const isDeclined = challenge.status === "declined";
  const isExpired = challenge.status === "expired";
  const isCancelled = challenge.status === "cancelled";

  const rankingMethod = challenge.rules?.rankingMethod || "pnl";
  const theme = CHALLENGE_THEMES[rankingMethod] || CHALLENGE_THEMES.pnl;
  const rankingInfo =
    RANKING_DESCRIPTIONS[rankingMethod] || RANKING_DESCRIPTIONS.pnl;

  // Live countdown
  const getTimeRemaining = (targetDate: string) => {
    const now = new Date();
    const target = new Date(targetDate);
    const diff = target.getTime() - now.getTime();

    if (diff < 0) return "Expired";

    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((diff % (1000 * 60)) / 1000);

    if (hours > 0) return `${hours}h ${minutes}m`;
    if (minutes > 0) return `${minutes}m ${seconds}s`;
    return `${seconds}s`;
  };

  useEffect(() => {
    const targetDate = isActive ? challenge.endTime : challenge.acceptDeadline;
    if (targetDate && (isActive || isPending)) {
      setLiveCountdown(getTimeRemaining(targetDate));
      const interval = setInterval(() => {
        setLiveCountdown(getTimeRemaining(targetDate));
      }, 1000);
      return () => clearInterval(interval);
    }
    return undefined;
  }, [isActive, isPending, challenge.endTime, challenge.acceptDeadline]);

  // Format date helper
  const formatDateTime = (dateStr: string) => {
    const date = new Date(dateStr);
    return date.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "short",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  // Get status style
  const getStatusStyle = () => {
    if (isCompleted) {
      if (isNoWinner)
        return {
          text: "NO WINNER",
          color: "text-gray-400/30",
          shadow: "rgba(156, 163, 175, 0.4)",
        };
      if (challenge.isTie)
        return {
          text: "TIE",
          color: "text-yellow-500/30",
          shadow: "rgba(234, 179, 8, 0.4)",
        };
      if (isWinner)
        return {
          text: "WON",
          color: "text-green-500/30",
          shadow: "rgba(34, 197, 94, 0.4)",
        };
      if (isLoser)
        return {
          text: "LOST",
          color: "text-red-500/30",
          shadow: "rgba(239, 68, 68, 0.4)",
        };
      // Fallback for completed but no outcome detected (shouldn't happen, but safe)
      return {
        text: "LOST",
        color: "text-red-500/30",
        shadow: "rgba(239, 68, 68, 0.4)",
      };
    }
    if (isCancelled)
      return {
        text: "CANCELLED",
        color: "text-red-500/30",
        shadow: "rgba(239, 68, 68, 0.4)",
      };
    if (isDeclined)
      return {
        text: "DECLINED",
        color: "text-gray-500/30",
        shadow: "rgba(156, 163, 175, 0.4)",
      };
    if (isExpired)
      return {
        text: "EXPIRED",
        color: "text-gray-500/30",
        shadow: "rgba(156, 163, 175, 0.4)",
      };
    if (isActive)
      return {
        text: "LIVE",
        color: "text-blue-500/25",
        shadow: "rgba(59, 130, 246, 0.3)",
      };
    if (isPending)
      return {
        text: "PENDING",
        color: "text-yellow-500/25",
        shadow: "rgba(234, 179, 8, 0.3)",
      };
    return null;
  };

  const statusStyle = getStatusStyle();

  // LIST VIEW
  if (viewMode === "list") {
    return (
      <Link href={`/challenges/${challenge._id}`}>
        <div
          className={`group relative overflow-hidden rounded-xl ${theme.bgPattern} border border-gray-700/50 hover:border-orange-500/50 transition-all duration-300 hover:shadow-xl hover:${theme.glow}`}
        >
          <div className="flex items-center gap-4 p-4">
            {/* Icon */}
            <div
              className={`flex-shrink-0 w-14 h-14 rounded-xl bg-gradient-to-br ${theme.gradient} flex items-center justify-center text-2xl shadow-lg ${theme.glow}`}
            >
              <GameIcon name="sword" size={30} />
            </div>

            {/* Main Info */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <h3 className="font-bold text-gray-100 truncate group-hover:text-orange-400 transition-colors">
                  vs {opponentName}
                </h3>
                {isActive && (
                  <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-blue-500 text-white text-[11px] font-bold animate-pulse">
                    LIVE
                  </span>
                )}
                {isCompleted && isNoWinner && (
                  <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-gray-600 text-white text-[11px] font-bold">
                    NO WINNER
                  </span>
                )}
                {isCompleted && !isNoWinner && challenge.isTie && (
                  <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-yellow-600 text-white text-[11px] font-bold">
                    TIE
                  </span>
                )}
                {isCompleted && !isNoWinner && !challenge.isTie && isWinner && (
                  <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-green-600 text-white text-[11px] font-bold">
                    WON
                  </span>
                )}
                {isCompleted && !isNoWinner && !challenge.isTie && isLoser && (
                  <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-red-500 text-white text-[11px] font-bold">
                    LOST
                  </span>
                )}
                {isPending && (
                  <span className="flex-shrink-0 px-2 py-0.5 rounded-full bg-yellow-500 text-black text-[11px] font-bold">
                    PENDING
                  </span>
                )}
              </div>
              <div className="flex items-center gap-3 text-sm text-gray-400">
                <span className="flex items-center gap-1">
                  <span
                    className={`w-2 h-2 rounded-full bg-gradient-to-r ${theme.gradient}`}
                  ></span>
                  {rankingInfo.name}
                </span>
                <span className="flex items-center gap-1">
                  <Clock className="h-3 w-3" />
                  {challenge.duration}m
                </span>
              </div>
            </div>

            {/* Prize */}
            <div className="flex-shrink-0 text-right px-3 border-l border-gray-700">
              <div className="flex items-center gap-1 text-yellow-500">
                <GameIcon name="trophy" size={18} />
                <span className="text-xl font-black">
                  {challenge.winnerPrize?.toFixed(0) || 0}
                </span>
              </div>
              <p className="text-xs text-gray-500">Winner Takes</p>
            </div>

            {/* Entry Fee */}
            <div className="flex-shrink-0 text-right px-4 border-l border-gray-700">
              <div className="text-lg font-bold text-gray-100">
                {challenge.entryFee}
              </div>
              <p className="text-xs text-gray-500">Entry Each</p>
            </div>

            {/* Countdown/Status */}
            <div className="flex-shrink-0 w-24 text-center">
              {(isPending || isActive) && (
                <div
                  className={`px-3 py-1.5 rounded-lg ${isActive ? "bg-blue-500/20 border border-blue-500/30" : "bg-yellow-500/20 border border-yellow-500/30"}`}
                >
                  <p
                    className={`text-xs font-mono font-bold ${isActive ? "text-blue-400" : "text-yellow-400"}`}
                  >
                    {liveCountdown}
                  </p>
                </div>
              )}
              {isCompleted && (
                <div
                  className={`px-3 py-1.5 rounded-lg ${
                    isNoWinner ? "bg-gray-500/20 border border-gray-500/30"
                    : challenge.isTie ? "bg-yellow-500/20 border border-yellow-500/30"
                    : isWinner ? "bg-green-500/20 border border-green-500/30"
                    : "bg-red-500/20 border border-red-500/30"
                  }`}
                >
                  <p
                    className={`text-xs font-bold ${
                      isNoWinner ? "text-gray-400"
                      : challenge.isTie ? "text-yellow-400"
                      : isWinner ? "text-green-400"
                      : "text-red-400"
                    }`}
                  >
                    {isNoWinner ? "NO WINNER" : challenge.isTie ? "TIE" : isWinner ? "WON" : "LOST"}
                  </p>
                </div>
              )}
            </div>

            {/* Arrow */}
            <ChevronRight className="h-5 w-5 text-gray-500 group-hover:text-orange-500 transition-colors" />
          </div>
        </div>
      </Link>
    );
  }

  // CARD VIEW (Default)
  const bgPattern =
    isCancelled || isDeclined || isExpired
      ? "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-gray-800/40 via-gray-900 to-gray-900"
      : isCompleted && isNoWinner
        ? "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-gray-800/40 via-gray-900 to-gray-900"
        : isCompleted && challenge.isTie
          ? "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-yellow-900/40 via-gray-900 to-gray-900"
          : isCompleted && isLoser
            ? "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-red-900/40 via-gray-900 to-gray-900"
            : isCompleted && isWinner
              ? "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-green-900/40 via-gray-900 to-gray-900"
              : theme.bgPattern;

  return (
    <div
      className={`group relative overflow-hidden rounded-2xl ${bgPattern} border ${
        isCancelled || isDeclined || isExpired ? "border-gray-700/50"
        : isCompleted && isNoWinner ? "border-gray-600/50 hover:border-gray-500/50"
        : isCompleted && challenge.isTie ? "border-yellow-700/50 hover:border-yellow-500/50"
        : isCompleted && isLoser ? "border-red-700/50 hover:border-red-500/50"
        : isCompleted && isWinner ? "border-green-700/50 hover:border-green-500/50"
        : "border-gray-700/50 hover:border-orange-500/50"
      } transition-all duration-500 hover:shadow-2xl hover:${theme.glow} hover:-translate-y-2`}
    >
      {/* Animated Background Effects */}
      <div className="absolute inset-0 opacity-30">
        <div
          className={`absolute top-0 right-0 w-64 h-64 bg-gradient-to-br ${theme.gradient} rounded-full blur-3xl -translate-y-32 translate-x-32 group-hover:scale-150 transition-transform duration-700`}
        ></div>
        <div
          className={`absolute bottom-0 left-0 w-48 h-48 bg-gradient-to-tr ${theme.gradient} rounded-full blur-3xl translate-y-24 -translate-x-24 group-hover:scale-150 transition-transform duration-700`}
        ></div>
      </div>

      {/* Large Diagonal Watermark for Status */}
      {statusStyle && (
        <div className="absolute inset-0 z-30 pointer-events-none flex items-center justify-center overflow-hidden">
          <div
            className={`font-black tracking-wider uppercase select-none text-4xl md:text-5xl ${statusStyle.color}`}
            style={{
              transform: "rotate(-25deg)",
              textShadow: `0 0 40px ${statusStyle.shadow}`,
              letterSpacing: "0.12em",
            }}
          >
            {statusStyle.text}
          </div>
        </div>
      )}

      {/* Status Badges */}
      <div className="absolute top-4 right-4 z-20 flex flex-col gap-2">
        {canRespond && (
          <span className="flex items-center gap-1 px-2 py-1 rounded-full bg-yellow-500/20 text-yellow-400 text-[11px] font-bold border border-yellow-500/40 animate-pulse">
            <Sparkles className="h-3 w-3" />
            RESPOND
          </span>
        )}
        {isChallenger && isPending && (
          <span className="flex items-center gap-1 px-2 py-1 rounded-full bg-blue-500/20 text-blue-400 text-[11px] font-bold border border-blue-500/40">
            <GameIcon name="sword" size={14} />
            SENT
          </span>
        )}
      </div>

      {/* Card Content */}
      <div className="relative z-10 p-6">
        {/* Challenge Type Badge */}
        <div className="flex justify-center mb-4">
          <div className="relative group/type cursor-default">
            <div
              className={`absolute inset-0 bg-gradient-to-r ${theme.gradient} rounded-xl blur opacity-50 group-hover/type:opacity-80 transition-opacity`}
            ></div>
            <div className="relative flex items-center gap-2 px-4 py-2 rounded-xl bg-gray-900/80 border border-gray-700 backdrop-blur">
              <GameIcon name="sword" size={22} />
              <div>
                <p
                  className={`text-sm font-black bg-gradient-to-r ${theme.gradient} bg-clip-text text-transparent`}
                >
                  1v1 Challenge
                </p>
                <p className="text-[11px] text-gray-400">{rankingInfo.name}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Opponent Name */}
        <h3 className="text-xl font-black text-center text-gray-100 mb-2 group-hover:text-orange-400 transition-colors">
          vs {opponentName}
        </h3>
        <p className="text-sm text-gray-400 text-center mb-4">
          {isChallenger ? "You challenged" : "Challenged you"}
        </p>

        {/* Winner Prize Pool - Casino Style */}
        <div className="relative mb-5">
          <div
            className={`absolute inset-0 bg-gradient-to-r from-yellow-500/20 via-amber-500/20 to-yellow-500/20 rounded-2xl blur-xl`}
          ></div>
          <div className="relative p-5 rounded-2xl bg-gradient-to-br from-yellow-500/10 via-amber-500/5 to-transparent border-2 border-yellow-500/40 overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-yellow-400 to-transparent"></div>
            <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-yellow-400 to-transparent"></div>

            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-1 mb-1">
                  <GameIcon name="crown" size={18} />
                  <p className="text-xs font-bold text-yellow-400 uppercase tracking-wider">
                    Winner Takes
                  </p>
                </div>
                {/* The pot, in the unit it is actually paid in, and no fiat equivalent - see
                    the same decision on `CompetitionCard`. */}
                <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 via-amber-300 to-yellow-500 drop-shadow-lg">
                    {formatVolts(challenge.winnerPrize ?? 0, {
                      unit: settings?.credits?.name,
                    })}
                  </span>
                </div>
              </div>
              <div className="relative">
                <div className="absolute inset-0 bg-yellow-500 rounded-xl blur-lg opacity-30 animate-pulse"></div>
                <div className="relative w-16 h-16 bg-gradient-to-br from-yellow-400 to-amber-600 rounded-xl flex items-center justify-center shadow-xl transform group-hover:rotate-12 transition-transform">
                  <GameIcon name="trophy" size={36} />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 gap-2 mb-4">
          <div className="relative overflow-hidden rounded-xl bg-gray-800/50 border border-gray-700/50 p-3">
            <div className="absolute top-0 right-0 w-8 h-8 bg-green-500/10 rounded-full blur-lg"></div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-green-500/20 flex items-center justify-center">
                <Zap className="h-4 w-4 text-green-400" />
              </div>
              <div>
                <p className="text-[11px] text-gray-500 uppercase">Entry Fee</p>
                <p className="text-sm font-bold text-gray-100">
                  {formatVolts(challenge.entryFee, {
                    unit: settings?.credits?.name,
                  })}
                </p>
              </div>
            </div>
          </div>

          <div className="relative overflow-hidden rounded-xl bg-gray-800/50 border border-gray-700/50 p-3">
            <div className="absolute top-0 right-0 w-8 h-8 bg-blue-500/10 rounded-full blur-lg"></div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-blue-500/20 flex items-center justify-center">
                <Users className="h-4 w-4 text-blue-400" />
              </div>
              <div>
                <p className="text-[11px] text-gray-500 uppercase">Players</p>
                <p className="text-sm font-bold text-gray-100">1v1</p>
              </div>
            </div>
          </div>

          <div className="relative overflow-hidden rounded-xl bg-gray-800/50 border border-gray-700/50 p-3">
            <div className="absolute top-0 right-0 w-8 h-8 bg-purple-500/10 rounded-full blur-lg"></div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-purple-500/20 flex items-center justify-center">
                <GameIcon name="target" size={18} />
              </div>
              <div>
                <p className="text-[11px] text-gray-500 uppercase">Capital</p>
                <p className="text-sm font-bold text-gray-100">
                  ${(challenge.startingCapital || 10000).toLocaleString()}
                </p>
              </div>
            </div>
          </div>

          <div className="relative overflow-hidden rounded-xl bg-gray-800/50 border border-gray-700/50 p-3">
            <div className="absolute top-0 right-0 w-8 h-8 bg-orange-500/10 rounded-full blur-lg"></div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-orange-500/20 flex items-center justify-center">
                <GameIcon name="timer" size={18} />
              </div>
              <div>
                <p className="text-[11px] text-gray-500 uppercase">Duration</p>
                <p className="text-sm font-bold text-gray-100">
                  {challenge.duration}m
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Countdown Timer */}
        {(isPending || isActive) && (
          <div
            className={`mb-4 p-3 rounded-xl ${isActive ? "bg-gradient-to-r from-blue-500/10 via-blue-500/10 to-blue-500/10 border border-blue-500/30" : "bg-gradient-to-r from-yellow-500/10 via-amber-500/10 to-yellow-500/10 border border-yellow-500/30"}`}
          >
            <div className="flex items-center justify-center gap-3">
              <Clock
                className={`h-4 w-4 ${isActive ? "text-blue-500" : "text-yellow-500"} animate-pulse`}
              />
              <div className="flex items-center gap-1">
                <span className="text-xs text-gray-400">
                  {isActive ? "Ends in" : "Accept by"}
                </span>
                <span
                  className={`px-2 py-1 rounded bg-gray-900/80 font-mono font-bold text-sm ${isActive ? "text-blue-400" : "text-yellow-400"}`}
                >
                  {liveCountdown}
                </span>
              </div>
              <Clock
                className={`h-4 w-4 ${isActive ? "text-blue-500" : "text-yellow-500"} animate-pulse`}
              />
            </div>
          </div>
        )}

        {/* Action Buttons */}
        {canRespond && onAccept && onDecline ? (
          <div className="flex gap-2">
            <Button
              onClick={() => onAccept(challenge._id)}
              disabled={responding}
              className="flex-1 font-black py-6 rounded-xl bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 text-white shadow-lg shadow-green-500/30 transition-all duration-300 transform hover:scale-105"
            >
              <CheckCircle className="h-5 w-5 mr-2" />
              Accept
            </Button>
            <Button
              onClick={() => onDecline(challenge._id)}
              disabled={responding}
              variant="outline"
              className="flex-1 font-bold py-6 rounded-xl border-2 border-red-600 text-red-400 hover:bg-red-500 hover:text-white transition-all duration-300"
            >
              Decline
            </Button>
          </div>
        ) : (
          <Link href={`/challenges/${challenge._id}`} className="block">
            <Button
              className={`w-full font-black text-base py-6 rounded-xl transition-all duration-300 transform hover:scale-105 active:scale-95 ${
                isActive
                  ? "bg-gradient-to-r from-blue-600 to-cyan-600 hover:from-blue-500 hover:to-cyan-500 text-white shadow-lg shadow-blue-500/30"
                  : isCompleted && isWinner
                    ? "bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 text-white shadow-lg shadow-green-500/30"
                    : `bg-gradient-to-r ${theme.gradient} text-gray-900 shadow-lg ${theme.glow} hover:shadow-xl`
              }`}
            >
              {isActive ? (
                <span className="flex items-center gap-2">
                  <GameIcon name="sword" size={22} />
                  Trade Now
                </span>
              ) : isCompleted ? (
                <span className="flex items-center gap-2">
                  <GameIcon name="trophy" size={22} />
                  View Results
                </span>
              ) : isPending && isChallenger ? (
                <span className="flex items-center gap-2">
                  <Clock className="h-5 w-5" />
                  Awaiting Response
                </span>
              ) : (
                <span className="flex items-center gap-2">
                  <GameIcon name="sword" size={22} />
                  View Challenge
                </span>
              )}
            </Button>
          </Link>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import {
  Trophy,
  TrendingUp,
  TrendingDown,
  Target,
  BarChart3,
  Activity,
  Clock,
  Flame,
  Award,
  Users,
  DollarSign,
  ArrowUpRight,
  ArrowDownRight,
  Zap,
  Shield,
  RefreshCw,
  Play,
  Eye,
  ChevronRight,
  Sparkles,
  Medal,
  Crown,
  AlertTriangle,
  Skull,
  Ban,
  CheckCircle,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import Link from "next/link";
import { useAppSettings } from "@/contexts/AppSettingsContext";
import { formatVolts } from "@/lib/utils/format-volts";

interface CompetitionRules {
  minimumTrades?: number;
  minimumWinRate?: number;
  disqualifyOnLiquidation?: boolean;
}

interface CompetitionDashboardProps {
  competitionId: string;
  initialParticipant: {
    _id: string;
    currentCapital: number;
    pnl: number;
    pnlPercentage: number;
    totalTrades: number;
    currentRank?: number;
    winningTrades?: number;
    losingTrades?: number;
    status?: string;
  } | null;
  competitionStatus: "upcoming" | "active" | "completed" | "cancelled";
  startTime: string;
  endTime: string;
  startingCapital: number;
  totalParticipants: number;
  competitionRules?: CompetitionRules;
}

interface AllTimeStats {
  // Competitions
  totalCompetitions: number;
  activeCompetitions: number;
  completedCompetitions: number;
  // Challenges
  totalChallenges: number;
  activeChallenges: number;
  completedChallenges: number;
  challengeWins: number;
  challengeLosses: number;
  // Combined
  totalContests: number;
  totalPnL: number;
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  bestRank: number | null;
  averageRank: number;
  totalPrizesWon: number;
  totalEntryFees: number;
  netProfit: number;
  winRate: number;
  averagePnLPerContest: number;
  biggestWin: number;
  biggestLoss: number;
  rankHistory: { date: string; rank: number; name: string; type: string }[];
  pnlHistory: { date: string; pnl: number; name: string; type: string }[];
}

interface CurrentStats {
  competitionName: string;
  competitionStatus: string;
  startingCapital: number;
  currentCapital: number;
  currentRank: number | null;
  totalParticipants: number;
  pnl: number;
  pnlPercentage: number;
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  winRate: number;
  openPositionsCount: number;
  unrealizedPnL: number;
  realizedPnL: number;
  equity: number;
  marginUsed: number;
  availableMargin: number;
  todayPnL: number;
  todayTrades: number;
  todayWinRate: number;
  winStreak: number;
  loseStreak: number;
  currentStreak: number;
  isOnWinStreak: boolean;
  avgWin: number;
  avgLoss: number;
  profitFactor: number;
  largestWin: number;
  largestLoss: number;
  avgHoldingTime: number;
}

interface EquityPoint {
  time: string;
  equity: number;
}

export default function CompetitionDashboard({
  competitionId,
  initialParticipant,
  competitionStatus,
  startTime,
  endTime,
  startingCapital,
  totalParticipants,
  competitionRules,
}: CompetitionDashboardProps) {
  const { settings } = useAppSettings();
  const [allTimeStats, setAllTimeStats] = useState<AllTimeStats | null>(null);
  const [currentStats, setCurrentStats] = useState<CurrentStats | null>(null);
  const [equityCurve, setEquityCurve] = useState<EquityPoint[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
  const [activeTab, setActiveTab] = useState("live");
  const [isRefreshing, setIsRefreshing] = useState(false);

  const isActive = competitionStatus === "active";
  const isCompleted = competitionStatus === "completed";
  const isUpcoming = competitionStatus === "upcoming";
  const isCancelled = competitionStatus === "cancelled";

  // Fetch comprehensive stats
  const fetchStats = useCallback(async () => {
    try {
      const response = await fetch(
        `/api/user/competition-stats?competitionId=${competitionId}`,
      );
      if (response.ok) {
        const data = await response.json();
        setAllTimeStats(data.allTimeStats);
        setCurrentStats(data.currentCompetitionStats);
        setEquityCurve(data.equityCurve || []);
        setLastUpdate(new Date());
      }
    } catch (error) {
      console.error("Failed to fetch competition stats:", error);
    } finally {
      setIsLoading(false);
    }
  }, [competitionId]);

  useEffect(() => {
    fetchStats();

    if (isActive) {
      const interval = setInterval(fetchStats, 30000);
      return () => clearInterval(interval);
    }
    return undefined;
  }, [fetchStats, isActive]);

  // Calculate equity curve chart points
  const chartData = useMemo(() => {
    if (equityCurve.length < 2) return null;

    const minEquity = Math.min(...equityCurve.map((p) => p.equity));
    const maxEquity = Math.max(...equityCurve.map((p) => p.equity));
    const range = maxEquity - minEquity || 1;

    const points = equityCurve
      .map((point, index) => {
        const x = (index / (equityCurve.length - 1)) * 100;
        const y = 100 - ((point.equity - minEquity) / range) * 100;
        return `${x},${y}`;
      })
      .join(" ");

    return { points, minEquity, maxEquity };
  }, [equityCurve]);

  // Ranking position indicator
  const getRankBadge = (rank: number | null | undefined, total: number) => {
    if (!rank)
      return {
        color: "text-gray-400",
        bg: "bg-gray-500/20",
        icon: null,
        label: "Unranked",
      };

    const percentile = (rank / total) * 100;

    if (rank === 1)
      return {
        color: "text-yellow-400",
        bg: "bg-yellow-500/20",
        icon: Crown,
        label: "1st Place",
      };
    if (rank === 2)
      return {
        color: "text-gray-300",
        bg: "bg-gray-400/20",
        icon: Medal,
        label: "2nd Place",
      };
    if (rank === 3)
      return {
        color: "text-orange-400",
        bg: "bg-orange-500/20",
        icon: Medal,
        label: "3rd Place",
      };
    if (percentile <= 10)
      return {
        color: "text-purple-400",
        bg: "bg-purple-500/20",
        icon: Award,
        label: "Top 10%",
      };
    if (percentile <= 25)
      return {
        color: "text-blue-400",
        bg: "bg-blue-500/20",
        icon: Trophy,
        label: "Top 25%",
      };
    if (percentile <= 50)
      return {
        color: "text-green-400",
        bg: "bg-green-500/20",
        icon: Target,
        label: "Top 50%",
      };
    return {
      color: "text-gray-400",
      bg: "bg-gray-500/20",
      icon: null,
      label: `#${rank}`,
    };
  };

  if (!initialParticipant) {
    return null;
  }

  if (isLoading) {
    return (
      <div className="rounded-2xl bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-slate-700/50 p-8">
        <div className="flex items-center justify-center gap-3">
          <RefreshCw className="h-6 w-6 text-blue-400 animate-spin" />
          <span className="text-slate-400">Loading your dashboard...</span>
        </div>
      </div>
    );
  }

  const stats = currentStats || {
    currentCapital: initialParticipant.currentCapital,
    pnl: initialParticipant.pnl,
    pnlPercentage: initialParticipant.pnlPercentage,
    totalTrades: initialParticipant.totalTrades,
    currentRank: initialParticipant.currentRank,
    winningTrades: initialParticipant.winningTrades || 0,
    losingTrades: initialParticipant.losingTrades || 0,
    winRate:
      initialParticipant.totalTrades > 0
        ? ((initialParticipant.winningTrades || 0) /
            initialParticipant.totalTrades) *
          100
        : 0,
    unrealizedPnL: 0,
    realizedPnL: initialParticipant.pnl,
    equity: initialParticipant.currentCapital,
    openPositionsCount: 0,
    todayPnL: 0,
    todayTrades: 0,
    winStreak: 0,
    profitFactor: 0,
    avgWin: 0,
    avgLoss: 0,
    totalParticipants,
  };

  const rankInfo = getRankBadge(
    stats.currentRank,
    stats.totalParticipants || totalParticipants,
  );

  // Check disqualification status
  const isLiquidated = initialParticipant?.status === "liquidated";
  const minimumTrades = competitionRules?.minimumTrades || 0;
  const needsMoreTrades =
    minimumTrades > 0 && stats.totalTrades < minimumTrades;
  const tradesRemaining = Math.max(0, minimumTrades - stats.totalTrades);
  const minimumWinRate = competitionRules?.minimumWinRate || 0;
  const winRate =
    stats.totalTrades > 0 ? (stats.winningTrades / stats.totalTrades) * 100 : 0;
  const belowWinRate = minimumWinRate > 0 && winRate < minimumWinRate;

  // Is user at risk of disqualification?
  const isDisqualified = isLiquidated;
  const isAtRisk =
    !isDisqualified && (needsMoreTrades || belowWinRate) && isActive;

  return (
    <div className="space-y-6">
      {/* ≡ƒÜ¿ DISQUALIFICATION STATUS / WARNINGS */}
      {/* Disqualified Banner */}
      {isDisqualified && (
        <div className="rounded-xl bg-gradient-to-r from-red-900/50 via-red-800/50 to-red-900/50 border-2 border-red-500/50 p-4 shadow-lg shadow-red-500/20 animate-pulse">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-red-500/30 rounded-xl">
              <Skull className="h-8 w-8 text-red-400" />
            </div>
            <div className="flex-1">
              <h3 className="text-xl font-bold text-red-400 flex items-center gap-2">
                <Ban className="h-5 w-5" />
                YOU ARE DISQUALIFIED
              </h3>
              <p className="text-sm text-red-300/80">
                {isLiquidated
                  ? "Your account was liquidated. You are no longer eligible for prizes in this competition."
                  : "You have been disqualified from this competition."}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* At Risk Warning */}
      {isAtRisk && !isDisqualified && (
        <div className="rounded-xl bg-gradient-to-r from-amber-900/30 via-orange-900/30 to-amber-900/30 border-2 border-amber-500/40 p-4">
          <div className="flex items-start gap-4">
            <div className="p-3 bg-amber-500/20 rounded-xl shrink-0">
              <AlertTriangle className="h-6 w-6 text-amber-400" />
            </div>
            <div className="flex-1 space-y-3">
              <div>
                <h3 className="text-lg font-bold text-amber-400 flex items-center gap-2">
                  ΓÜá∩╕Å DISQUALIFICATION WARNING
                </h3>
                <p className="text-sm text-amber-300/70">
                  You are at risk of being disqualified! Take action before the
                  competition ends.
                </p>
              </div>

              <div className="space-y-2">
                {/* Minimum Trades Warning */}
                {needsMoreTrades && (
                  <div className="flex items-center justify-between p-3 bg-gray-900/50 rounded-lg border border-amber-500/30">
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="h-4 w-4 text-orange-400" />
                      <span className="text-sm text-gray-300">
                        Minimum Trades Required
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span
                        className={`text-lg font-bold ${stats.totalTrades < minimumTrades ? "text-red-400" : "text-green-400"}`}
                      >
                        {stats.totalTrades}/{minimumTrades}
                      </span>
                      <span className="text-xs text-orange-400 font-semibold px-2 py-1 bg-orange-500/20 rounded">
                        {tradesRemaining} more needed!
                      </span>
                    </div>
                  </div>
                )}

                {/* Win Rate Warning */}
                {belowWinRate && (
                  <div className="flex items-center justify-between p-3 bg-gray-900/50 rounded-lg border border-yellow-500/30">
                    <div className="flex items-center gap-2">
                      <Target className="h-4 w-4 text-yellow-400" />
                      <span className="text-sm text-gray-300">
                        Minimum Win Rate Required
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span
                        className={`text-lg font-bold ${winRate < minimumWinRate ? "text-red-400" : "text-green-400"}`}
                      >
                        {winRate.toFixed(1)}%
                      </span>
                      <span className="text-xs text-yellow-400">
                        / {minimumWinRate}% min
                      </span>
                    </div>
                  </div>
                )}

                {/* Liquidation Warning if enabled */}
                {competitionRules?.disqualifyOnLiquidation && (
                  <div className="flex items-center gap-2 p-2 bg-red-500/10 rounded-lg border border-red-500/20">
                    <Skull className="h-4 w-4 text-red-400" />
                    <span className="text-xs text-red-300">
                      Remember: Getting liquidated = instant disqualification!
                    </span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Qualified Badge - Show when all requirements are met */}
      {!isDisqualified &&
        !isAtRisk &&
        competitionRules &&
        (minimumTrades > 0 || minimumWinRate > 0) &&
        isActive && (
          <div className="rounded-xl bg-gradient-to-r from-green-900/20 via-emerald-900/20 to-green-900/20 border border-green-500/30 p-3">
            <div className="flex items-center gap-3">
              <CheckCircle className="h-5 w-5 text-green-400" />
              <span className="text-sm text-green-400 font-medium">
                Γ£à You meet all qualification requirements! Keep trading to
                improve your rank.
              </span>
              {minimumTrades > 0 && (
                <span className="text-xs text-green-300/70 ml-auto">
                  Trades: {stats.totalTrades}/{minimumTrades} Γ£ô
                </span>
              )}
            </div>
          </div>
        )}

      {/* Main Dashboard Card */}
      <div className="rounded-2xl bg-gradient-to-br from-slate-900 via-slate-800/95 to-slate-900 border border-slate-700/50 overflow-hidden shadow-2xl">
        {/* Header with Status */}
        <div className="relative px-6 py-4 border-b border-slate-700/50 bg-gradient-to-r from-slate-800/50 to-transparent">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className={`p-3 rounded-xl ${rankInfo.bg}`}>
                {rankInfo.icon ? (
                  <rankInfo.icon className={`h-6 w-6 ${rankInfo.color}`} />
                ) : (
                  <Trophy className={`h-6 w-6 ${rankInfo.color}`} />
                )}
              </div>
              <div>
                <h2 className="text-xl font-bold text-white flex items-center gap-3 flex-wrap">
                  Your Competition Dashboard
                  {isActive && (
                    <span className="px-3 py-1 rounded-full bg-gradient-to-r from-green-500/30 to-emerald-500/30 text-green-400 text-xs font-bold animate-pulse flex items-center gap-1.5 border border-green-500/40 shadow-lg shadow-green-500/20">
                      <span className="w-2 h-2 bg-green-400 rounded-full animate-ping"></span>
                      <span className="w-2 h-2 bg-green-400 rounded-full absolute"></span>
                      LIVE NOW
                    </span>
                  )}
                  {isCompleted && (
                    <span className="px-3 py-1 rounded-full bg-gradient-to-r from-purple-500/30 to-violet-500/30 text-purple-400 text-xs font-bold border border-purple-500/40">
                      ≡ƒÅü FINAL
                    </span>
                  )}
                  {isUpcoming && (
                    <span className="px-4 py-1.5 rounded-full bg-gradient-to-r from-amber-500/30 via-orange-500/30 to-yellow-500/30 text-amber-300 text-sm font-bold flex items-center gap-2 border border-amber-500/50 shadow-lg shadow-amber-500/20 animate-pulse">
                      <Clock className="h-4 w-4 text-amber-400" />
                      <span className="bg-gradient-to-r from-amber-300 to-yellow-300 bg-clip-text text-transparent">
                        Starting Soon
                      </span>
                    </span>
                  )}
                  {isCancelled && (
                    <span className="px-4 py-1.5 rounded-full bg-gradient-to-r from-red-500/30 via-red-600/30 to-red-700/30 text-red-300 text-sm font-bold flex items-center gap-2 border border-red-500/50 shadow-lg shadow-red-500/20">
                      <Ban className="h-4 w-4 text-red-400" />
                      <span className="text-red-300">CANCELLED</span>
                    </span>
                  )}
                </h2>
                <p className="text-sm text-slate-400 flex items-center gap-2 mt-1">
                  <span className={rankInfo.color}>{rankInfo.label}</span>
                  <span className="text-slate-600">ΓÇó</span>
                  <span>
                    Rank #{stats.currentRank || "ΓÇö"} of{" "}
                    {stats.totalParticipants || totalParticipants}
                  </span>
                </p>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex items-center gap-2">
              {isCompleted && (
                <Link href={`/competitions/${competitionId}/results`}>
                  <Button
                    className="bg-gradient-to-r from-purple-500 to-violet-600 hover:from-purple-600 hover:to-violet-700 text-white font-semibold
                      active:scale-95 transition-all duration-150 shadow-lg hover:shadow-purple-500/25"
                  >
                    <BarChart3 className="h-4 w-4 mr-2" />
                    View Results
                  </Button>
                </Link>
              )}
            </div>
          </div>

          {/* Last update indicator */}
          <div className="absolute bottom-2 right-4 text-xs text-slate-500 flex items-center gap-1">
            <RefreshCw className="h-3 w-3" />
            Updated {lastUpdate.toLocaleTimeString()}
          </div>
        </div>

        {/* Tabs Navigation */}
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <div className="px-6 pt-4 border-b border-slate-700/30">
            <TabsList className="bg-slate-800/50 p-1 rounded-xl">
              <TabsTrigger
                value="live"
                className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-blue-500 data-[state=active]:to-cyan-500 
                  data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:shadow-blue-500/25
                  rounded-lg px-4 transition-all duration-200 active:scale-95
                  hover:bg-slate-700/50 data-[state=inactive]:text-slate-400"
              >
                <Activity className="h-4 w-4 mr-2" />
                Live Stats
              </TabsTrigger>
              <TabsTrigger
                value="performance"
                className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-purple-500 data-[state=active]:to-pink-500 
                  data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:shadow-purple-500/25
                  rounded-lg px-4 transition-all duration-200 active:scale-95
                  hover:bg-slate-700/50 data-[state=inactive]:text-slate-400"
              >
                <BarChart3 className="h-4 w-4 mr-2" />
                Performance
              </TabsTrigger>
              <TabsTrigger
                value="alltime"
                className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-amber-500 data-[state=active]:to-orange-500 
                  data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:shadow-amber-500/25
                  rounded-lg px-4 transition-all duration-200 active:scale-95
                  hover:bg-slate-700/50 data-[state=inactive]:text-slate-400"
              >
                <Trophy className="h-4 w-4 mr-2" />
                All-Time
              </TabsTrigger>
            </TabsList>
          </div>

          {/* Live Stats Tab */}
          <TabsContent value="live" className="p-6 space-y-6 mt-0">
            {/* Primary Stats Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {/* Current Capital */}
              <div className="p-4 rounded-xl bg-gradient-to-br from-slate-800/80 to-slate-800/40 border border-slate-700/50 hover:border-blue-500/30 transition-colors">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">
                    Capital
                  </span>
                  <DollarSign className="h-4 w-4 text-blue-400" />
                </div>
                <p
                  className="text-2xl font-bold text-white"
                  suppressHydrationWarning
                >
                  $
                  {stats.currentCapital?.toLocaleString(undefined, {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2,
                  }) || "0.00"}
                </p>
                <p className="text-xs text-slate-500 mt-1">
                  Started: ${startingCapital?.toLocaleString()}
                </p>
              </div>

              {/* P&L */}
              <div
                className={`p-4 rounded-xl border transition-colors ${
                  stats.pnl >= 0
                    ? "bg-gradient-to-br from-green-500/10 to-green-500/5 border-green-500/30 hover:border-green-500/50"
                    : "bg-gradient-to-br from-red-500/10 to-red-500/5 border-red-500/30 hover:border-red-500/50"
                }`}
              >
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">
                    Total P&L
                  </span>
                  {stats.pnl >= 0 ? (
                    <TrendingUp className="h-4 w-4 text-green-400" />
                  ) : (
                    <TrendingDown className="h-4 w-4 text-red-400" />
                  )}
                </div>
                <p
                  className={`text-2xl font-bold ${stats.pnl >= 0 ? "text-green-400" : "text-red-400"}`}
                >
                  {stats.pnl >= 0 ? "+" : ""}${stats.pnl?.toFixed(2) || "0.00"}
                </p>
                <p
                  className={`text-xs mt-1 ${stats.pnlPercentage >= 0 ? "text-green-400/70" : "text-red-400/70"}`}
                >
                  {stats.pnlPercentage >= 0 ? "+" : ""}
                  {stats.pnlPercentage?.toFixed(2) || "0.00"}% ROI
                </p>
              </div>

              {/* Win Rate */}
              <div className="p-4 rounded-xl bg-gradient-to-br from-slate-800/80 to-slate-800/40 border border-slate-700/50 hover:border-purple-500/30 transition-colors">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">
                    Win Rate
                  </span>
                  <Target className="h-4 w-4 text-purple-400" />
                </div>
                <p className="text-2xl font-bold text-white">
                  {stats.winRate?.toFixed(1) || "0.0"}%
                </p>
                <p className="text-xs text-slate-500 mt-1">
                  {stats.winningTrades || 0}W / {stats.losingTrades || 0}L
                </p>
              </div>

              {/* Rank */}
              <div
                className={`p-4 rounded-xl border transition-colors ${rankInfo.bg} border-slate-700/50`}
              >
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">
                    Your Rank
                  </span>
                  {rankInfo.icon ? (
                    <rankInfo.icon className={`h-4 w-4 ${rankInfo.color}`} />
                  ) : (
                    <Trophy className="h-4 w-4 text-amber-400" />
                  )}
                </div>
                <p className={`text-2xl font-bold ${rankInfo.color}`}>
                  #{stats.currentRank || "ΓÇö"}
                </p>
                <p className="text-xs text-slate-500 mt-1">
                  of {stats.totalParticipants || totalParticipants} traders
                </p>
              </div>
            </div>

            {/* Equity Chart */}
            {chartData && equityCurve.length > 1 && (
              <div className="p-4 rounded-xl bg-gradient-to-br from-slate-800/80 to-slate-800/40 border border-slate-700/50">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                    <BarChart3 className="h-4 w-4 text-cyan-400" />
                    Equity Curve
                  </h3>
                  <div className="flex items-center gap-4 text-xs">
                    <span className="text-slate-400">
                      Min:{" "}
                      <span className="text-white font-medium">
                        ${chartData.minEquity.toFixed(2)}
                      </span>
                    </span>
                    <span className="text-slate-400">
                      Max:{" "}
                      <span className="text-white font-medium">
                        ${chartData.maxEquity.toFixed(2)}
                      </span>
                    </span>
                  </div>
                </div>
                <div className="h-32 relative">
                  <svg
                    className="w-full h-full"
                    viewBox="0 0 100 100"
                    preserveAspectRatio="none"
                  >
                    {/* Grid lines */}
                    <line
                      x1="0"
                      y1="25"
                      x2="100"
                      y2="25"
                      stroke="rgba(100,116,139,0.2)"
                      strokeWidth="0.5"
                    />
                    <line
                      x1="0"
                      y1="50"
                      x2="100"
                      y2="50"
                      stroke="rgba(100,116,139,0.2)"
                      strokeWidth="0.5"
                    />
                    <line
                      x1="0"
                      y1="75"
                      x2="100"
                      y2="75"
                      stroke="rgba(100,116,139,0.2)"
                      strokeWidth="0.5"
                    />

                    {/* Starting capital line */}
                    {(() => {
                      const startY =
                        100 -
                        ((startingCapital - chartData.minEquity) /
                          (chartData.maxEquity - chartData.minEquity || 1)) *
                          100;
                      return (
                        <line
                          x1="0"
                          y1={startY}
                          x2="100"
                          y2={startY}
                          stroke="rgba(59,130,246,0.3)"
                          strokeWidth="0.5"
                          strokeDasharray="2,2"
                        />
                      );
                    })()}

                    {/* Equity line */}
                    <polyline
                      fill="none"
                      stroke={stats.pnl >= 0 ? "#22c55e" : "#ef4444"}
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      points={chartData.points}
                      vectorEffect="non-scaling-stroke"
                    />

                    {/* Area fill */}
                    <polygon
                      fill={
                        stats.pnl >= 0
                          ? "rgba(34,197,94,0.1)"
                          : "rgba(239,68,68,0.1)"
                      }
                      points={`0,100 ${chartData.points} 100,100`}
                    />
                  </svg>
                </div>
              </div>
            )}

            {/* Secondary Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {/* Total Trades */}
              <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-all duration-200 hover:bg-slate-800/70">
                <p className="text-xs text-slate-400 mb-1">Total Trades</p>
                <p className="text-lg font-bold text-white">
                  {stats.totalTrades || 0}
                </p>
              </div>

              {/* Open Positions */}
              <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-cyan-500/30 transition-all duration-200 hover:bg-slate-800/70">
                <p className="text-xs text-slate-400 mb-1">Open Positions</p>
                <p className="text-lg font-bold text-cyan-400">
                  {currentStats?.openPositionsCount || 0}
                </p>
              </div>

              {/* Unrealized P&L */}
              <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-all duration-200 hover:bg-slate-800/70">
                <p className="text-xs text-slate-400 mb-1">Unrealized P&L</p>
                <p
                  className={`text-lg font-bold ${(currentStats?.unrealizedPnL || 0) >= 0 ? "text-green-400" : "text-red-400"}`}
                >
                  {(currentStats?.unrealizedPnL || 0) >= 0 ? "+" : ""}$
                  {(currentStats?.unrealizedPnL || 0).toFixed(2)}
                </p>
              </div>

              {/* Today's P&L */}
              <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-all duration-200 hover:bg-slate-800/70">
                <p className="text-xs text-slate-400 mb-1">Today&apos;s P&L</p>
                <p
                  className={`text-lg font-bold ${(currentStats?.todayPnL || 0) >= 0 ? "text-green-400" : "text-red-400"}`}
                >
                  {(currentStats?.todayPnL || 0) >= 0 ? "+" : ""}$
                  {(currentStats?.todayPnL || 0).toFixed(2)}
                </p>
              </div>
            </div>
          </TabsContent>

          {/* Performance Tab */}
          <TabsContent value="performance" className="p-6 space-y-6 mt-0">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Trading Stats */}
              <div className="space-y-4">
                <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                  <BarChart3 className="h-4 w-4 text-purple-400" />
                  Trading Statistics
                </h3>

                <div className="grid grid-cols-2 gap-3">
                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-green-500/30 transition-all duration-200 hover:bg-slate-800/70">
                    <p className="text-xs text-slate-400 mb-1">Avg Win</p>
                    <p className="text-lg font-bold text-green-400">
                      +${(currentStats?.avgWin || 0).toFixed(2)}
                    </p>
                  </div>

                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-red-500/30 transition-all duration-200 hover:bg-slate-800/70">
                    <p className="text-xs text-slate-400 mb-1">Avg Loss</p>
                    <p className="text-lg font-bold text-red-400">
                      -${Math.abs(currentStats?.avgLoss || 0).toFixed(2)}
                    </p>
                  </div>

                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-green-500/30 transition-all duration-200 hover:bg-slate-800/70">
                    <p className="text-xs text-slate-400 mb-1">Largest Win</p>
                    <p className="text-lg font-bold text-green-400">
                      +${(currentStats?.largestWin || 0).toFixed(2)}
                    </p>
                  </div>

                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-red-500/30 transition-all duration-200 hover:bg-slate-800/70">
                    <p className="text-xs text-slate-400 mb-1">Largest Loss</p>
                    <p className="text-lg font-bold text-red-400">
                      -${Math.abs(currentStats?.largestLoss || 0).toFixed(2)}
                    </p>
                  </div>

                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-all duration-200 hover:bg-slate-800/70">
                    <p className="text-xs text-slate-400 mb-1">Profit Factor</p>
                    <p
                      className={`text-lg font-bold ${(currentStats?.profitFactor || 0) >= 1 ? "text-green-400" : (currentStats?.profitFactor || 0) === 0 ? "text-slate-400" : "text-red-400"}`}
                    >
                      {(currentStats?.profitFactor || 0) >= 999
                        ? "Γê₧"
                        : (currentStats?.profitFactor || 0).toFixed(2)}
                    </p>
                  </div>

                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-all duration-200 hover:bg-slate-800/70">
                    <p className="text-xs text-slate-400 mb-1">Avg Hold Time</p>
                    <p className="text-lg font-bold text-white">
                      {(currentStats?.avgHoldingTime || 0).toFixed(0)}m
                    </p>
                  </div>
                </div>
              </div>

              {/* Streaks & Momentum */}
              <div className="space-y-4">
                <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                  <Flame className="h-4 w-4 text-orange-400" />
                  Streaks & Momentum
                </h3>

                <div className="grid grid-cols-2 gap-3">
                  <div
                    className={`p-4 rounded-lg border ${
                      currentStats?.isOnWinStreak
                        ? "bg-gradient-to-br from-green-500/20 to-green-500/5 border-green-500/30"
                        : "bg-slate-800/50 border-slate-700/30"
                    }`}
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <Flame
                        className={`h-4 w-4 ${currentStats?.isOnWinStreak ? "text-green-400" : "text-slate-400"}`}
                      />
                      <p className="text-xs text-slate-400">Win Streak</p>
                    </div>
                    <p
                      className={`text-2xl font-bold ${currentStats?.isOnWinStreak && (currentStats?.winStreak || 0) > 0 ? "text-green-400" : "text-white"}`}
                    >
                      {currentStats?.winStreak || 0}
                    </p>
                    {currentStats?.isOnWinStreak &&
                      (currentStats?.winStreak || 0) >= 3 && (
                        <p className="text-xs text-green-400 mt-1 flex items-center gap-1">
                          <Sparkles className="h-3 w-3" /> On fire!
                        </p>
                      )}
                  </div>

                  <div
                    className={`p-4 rounded-lg border ${
                      !currentStats?.isOnWinStreak &&
                      (currentStats?.loseStreak || 0) > 0
                        ? "bg-gradient-to-br from-red-500/20 to-red-500/5 border-red-500/30"
                        : "bg-slate-800/50 border-slate-700/30"
                    }`}
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <TrendingDown
                        className={`h-4 w-4 ${!currentStats?.isOnWinStreak && (currentStats?.loseStreak || 0) > 0 ? "text-red-400" : "text-slate-400"}`}
                      />
                      <p className="text-xs text-slate-400">Lose Streak</p>
                    </div>
                    <p
                      className={`text-2xl font-bold ${!currentStats?.isOnWinStreak && (currentStats?.loseStreak || 0) > 0 ? "text-red-400" : "text-white"}`}
                    >
                      {currentStats?.loseStreak || 0}
                    </p>
                  </div>
                </div>

                {/* Win Rate Visual */}
                <div className="p-4 rounded-lg bg-slate-800/50 border border-slate-700/30">
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-xs text-slate-400">
                      Win Rate Distribution
                    </p>
                    <p className="text-sm font-bold text-white">
                      {(stats.winRate || 0).toFixed(1)}%
                    </p>
                  </div>
                  <div className="h-3 bg-slate-700/50 rounded-full overflow-hidden flex">
                    <div
                      className="h-full bg-gradient-to-r from-green-500 to-emerald-400 transition-all duration-500"
                      style={{ width: `${stats.winRate || 0}%` }}
                    />
                    <div
                      className="h-full bg-gradient-to-r from-red-500 to-rose-400"
                      style={{ width: `${100 - (stats.winRate || 0)}%` }}
                    />
                  </div>
                  <div className="flex justify-between mt-2 text-xs">
                    <span className="text-green-400">
                      {stats.winningTrades || 0} wins
                    </span>
                    <span className="text-red-400">
                      {stats.losingTrades || 0} losses
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </TabsContent>

          {/* All-Time Tab */}
          <TabsContent value="alltime" className="p-6 space-y-6 mt-0">
            {allTimeStats ? (
              <>
                {/* Career Overview - Competitions & Challenges */}
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                  <div className="p-4 rounded-xl bg-gradient-to-br from-amber-500/10 to-amber-500/5 border border-amber-500/30">
                    <div className="flex items-center gap-2 mb-2">
                      <Trophy className="h-4 w-4 text-amber-400" />
                      <p className="text-xs text-slate-400">Competitions</p>
                    </div>
                    <p className="text-2xl font-bold text-white">
                      {allTimeStats.totalCompetitions}
                    </p>
                    <p className="text-xs text-slate-500 mt-1">
                      {allTimeStats.completedCompetitions} completed
                    </p>
                  </div>

                  <div className="p-4 rounded-xl bg-gradient-to-br from-orange-500/10 to-orange-500/5 border border-orange-500/30">
                    <div className="flex items-center gap-2 mb-2">
                      <Zap className="h-4 w-4 text-orange-400" />
                      <p className="text-xs text-slate-400">1v1 Challenges</p>
                    </div>
                    <p className="text-2xl font-bold text-white">
                      {allTimeStats.totalChallenges || 0}
                    </p>
                    <p className="text-xs text-slate-500 mt-1">
                      <span className="text-green-400">
                        {allTimeStats.challengeWins || 0}W
                      </span>
                      {" / "}
                      <span className="text-red-400">
                        {allTimeStats.challengeLosses || 0}L
                      </span>
                    </p>
                  </div>

                  <div className="p-4 rounded-xl bg-gradient-to-br from-purple-500/10 to-purple-500/5 border border-purple-500/30">
                    <div className="flex items-center gap-2 mb-2">
                      <Medal className="h-4 w-4 text-purple-400" />
                      <p className="text-xs text-slate-400">Best Rank</p>
                    </div>
                    <p className="text-2xl font-bold text-white">
                      {allTimeStats.bestRank
                        ? `#${allTimeStats.bestRank}`
                        : "N/A"}
                    </p>
                    <p className="text-xs text-slate-500 mt-1">
                      Avg:{" "}
                      {allTimeStats.averageRank && allTimeStats.averageRank > 0
                        ? `#${allTimeStats.averageRank.toFixed(1)}`
                        : "N/A"}
                    </p>
                  </div>

                  <div className="p-4 rounded-xl bg-gradient-to-br from-cyan-500/10 to-cyan-500/5 border border-cyan-500/30">
                    <div className="flex items-center gap-2 mb-2">
                      <Award className="h-4 w-4 text-cyan-400" />
                      <p className="text-xs text-slate-400">Prizes Won</p>
                    </div>
                    <p className="text-2xl font-bold text-yellow-400">
                      {formatVolts(allTimeStats.totalPrizesWon ?? 0, {
                        unit: settings?.credits?.name,
                      })}
                    </p>
                    <p className="text-xs text-slate-500 mt-1">
                      Net:{" "}
                      {formatVolts(allTimeStats.netProfit ?? 0, {
                        unit: settings?.credits?.name,
                      })}
                    </p>
                  </div>
                </div>

                {/* P&L Summary */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                  <div
                    className={`p-4 rounded-xl border ${
                      (allTimeStats.totalPnL || 0) >= 0
                        ? "bg-gradient-to-br from-green-500/10 to-green-500/5 border-green-500/30"
                        : "bg-gradient-to-br from-red-500/10 to-red-500/5 border-red-500/30"
                    }`}
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <TrendingUp
                        className={`h-4 w-4 ${(allTimeStats.totalPnL || 0) >= 0 ? "text-green-400" : "text-red-400"}`}
                      />
                      <p className="text-xs text-slate-400">Total Career P&L</p>
                    </div>
                    <p
                      className={`text-3xl font-bold ${(allTimeStats.totalPnL || 0) >= 0 ? "text-green-400" : "text-red-400"}`}
                    >
                      {(allTimeStats.totalPnL || 0) >= 0 ? "+" : ""}$
                      {(allTimeStats.totalPnL || 0).toFixed(2)}
                    </p>
                    <p className="text-xs text-slate-500 mt-1">
                      Avg: $
                      {(allTimeStats.averagePnLPerContest || 0).toFixed(2)} per
                      contest
                    </p>
                  </div>

                  <div className="p-4 rounded-xl bg-slate-800/50 border border-slate-700/30">
                    <div className="flex items-center gap-2 mb-2">
                      <Target className="h-4 w-4 text-blue-400" />
                      <p className="text-xs text-slate-400">
                        Trading Performance
                      </p>
                    </div>
                    <div className="grid grid-cols-2 gap-2 mt-2">
                      <div>
                        <p className="text-2xl font-bold text-white">
                          {allTimeStats.totalTrades || 0}
                        </p>
                        <p className="text-xs text-slate-500">Total Trades</p>
                      </div>
                      <div>
                        <p className="text-2xl font-bold text-white">
                          {(allTimeStats.winRate || 0).toFixed(1)}%
                        </p>
                        <p className="text-xs text-slate-500">Win Rate</p>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Career Trading Stats */}
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-colors">
                    <p className="text-xs text-slate-400 mb-1">
                      Total Contests
                    </p>
                    <p className="text-lg font-bold text-white">
                      {allTimeStats.totalContests || 0}
                    </p>
                  </div>
                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-colors">
                    <p className="text-xs text-slate-400 mb-1">
                      Entry Fees Paid
                    </p>
                    <p className="text-lg font-bold text-amber-400">
                      {formatVolts(allTimeStats.totalEntryFees ?? 0, {
                        unit: settings?.credits?.name,
                      })}
                    </p>
                  </div>
                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-colors">
                    <p className="text-xs text-slate-400 mb-1">Biggest Win</p>
                    <p className="text-lg font-bold text-green-400">
                      +${(allTimeStats.biggestWin || 0).toFixed(2)}
                    </p>
                  </div>
                  <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700/30 hover:border-slate-600/50 transition-colors">
                    <p className="text-xs text-slate-400 mb-1">Biggest Loss</p>
                    <p className="text-lg font-bold text-red-400">
                      {(allTimeStats.biggestLoss || 0) < 0 ? "" : "-"}$
                      {Math.abs(allTimeStats.biggestLoss || 0).toFixed(2)}
                    </p>
                  </div>
                </div>

                {/* P&L History Mini Chart */}
                <div className="p-4 rounded-xl bg-slate-800/50 border border-slate-700/30">
                  <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
                    <BarChart3 className="h-4 w-4 text-amber-400" />
                    Contest History
                  </h3>
                  {allTimeStats.pnlHistory &&
                  allTimeStats.pnlHistory.length > 0 ? (
                    <>
                      <div className="flex items-end gap-1 h-20">
                        {allTimeStats.pnlHistory
                          .slice(-12)
                          .map((item, index) => {
                            const maxPnl = Math.max(
                              ...allTimeStats.pnlHistory.map((h) =>
                                Math.abs(h.pnl),
                              ),
                              1,
                            );
                            const height =
                              maxPnl > 0
                                ? (Math.abs(item.pnl) / maxPnl) * 100
                                : 5;
                            const isChallenge = item.type === "challenge";
                            return (
                              <div
                                key={index}
                                className="flex-1 flex flex-col justify-end cursor-pointer group"
                                title={`${item.name} (${item.type}): ${item.pnl >= 0 ? "+" : ""}$${item.pnl.toFixed(2)}`}
                              >
                                <div
                                  className={`rounded-t transition-all duration-200 group-hover:opacity-80 group-hover:scale-y-105 origin-bottom ${
                                    item.pnl >= 0
                                      ? isChallenge
                                        ? "bg-orange-500"
                                        : "bg-green-500"
                                      : "bg-red-500"
                                  }`}
                                  style={{
                                    height: `${Math.max(height, 8)}%`,
                                    minHeight: "4px",
                                  }}
                                />
                              </div>
                            );
                          })}
                      </div>
                      <div className="flex items-center justify-center gap-4 mt-3 text-xs text-slate-500">
                        <span className="flex items-center gap-1">
                          <span className="w-2 h-2 rounded-full bg-green-500"></span>
                          Competition Win
                        </span>
                        <span className="flex items-center gap-1">
                          <span className="w-2 h-2 rounded-full bg-orange-500"></span>
                          Challenge Win
                        </span>
                        <span className="flex items-center gap-1">
                          <span className="w-2 h-2 rounded-full bg-red-500"></span>
                          Loss
                        </span>
                      </div>
                    </>
                  ) : (
                    <div className="flex items-center justify-center h-20 text-slate-500 text-sm">
                      <p>Complete contests to see your history chart</p>
                    </div>
                  )}
                </div>
              </>
            ) : (
              <div className="text-center py-8">
                <Trophy className="h-12 w-12 text-slate-600 mx-auto mb-3" />
                <p className="text-slate-400">
                  Complete competitions or challenges to see your all-time
                  stats!
                </p>
              </div>
            )}
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { cn } from "@/lib/utils";
import Image from "next/image";
import { Skull, Target, Swords, Crown, Loader2 } from "lucide-react";
import { useAppSettings } from "@/contexts/AppSettingsContext";
import { formatVolts } from "@/lib/utils/format-volts";

interface RankingEntry {
  rank: number;
  userId: string;
  username: string;
  profitPercent: number;
  displayValue: number;
  liveEquity: number;
  potentialReward: number;
  distanceToFirst: number;
  isDisqualified: boolean;
  status: string;
  rankingMethod?: string;
  isSeparator?: boolean;
}

interface GameLiveRankingPanelProps {
  competitionId: string;
  userId?: string;
  className?: string;
}

export default function GameLiveRankingPanel({
  competitionId,
  userId,
  className,
}: GameLiveRankingPanelProps) {
  const { settings } = useAppSettings();
  // See the note in `LiveRankingPanel`: the ranking metric is simulated trading capital and
  // keeps its own symbol, while the prize pool and the potential reward are credits.
  const currSymbol = settings?.currency?.symbol || "Γé¼";
  const unit = settings?.credits?.name;
  const [rankings, setRankings] = useState<RankingEntry[]>([]);
  const [userRank, setUserRank] = useState<number | null>(null);
  const [totalParticipants, setTotalParticipants] = useState(0);
  const [prizePool, setPrizePool] = useState(0);
  const [rankingMethod, setRankingMethod] = useState<string>("pnl");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchRankings = useCallback(async () => {
    try {
      const response = await fetch(
        `/api/competitions/${competitionId}/live-ranking`,
      );
      if (!response.ok) {
        const data = await response.json();
        if (data.status === "completed" || data.status === "cancelled") {
          setError("Competition ended");
          return;
        }
        throw new Error(data.error || "Failed to fetch");
      }

      const data = await response.json();
      setRankings(data.rankings || []);
      setUserRank(data.userRank);
      setTotalParticipants(data.totalParticipants || 0);
      setPrizePool(data.prizePool || 0);
      setRankingMethod(data.rankingMethod || "pnl");
      setError(null);

      if (data.isLastManStanding && data.lastManUserId === userId) {
        window.dispatchEvent(
          new CustomEvent("lastManStanding", {
            detail: { competitionId, prizePool: data.prizePool || 0 },
          }),
        );
      }
    } catch (err) {
      console.error("Error fetching rankings:", err);
      setError("Failed to load");
    } finally {
      setLoading(false);
    }
  }, [competitionId, userId]);

  useEffect(() => {
    fetchRankings();
    // Poll every 15 seconds (reduced from 5s to lower server load)
    const interval = setInterval(fetchRankings, 15000);
    return () => clearInterval(interval);
  }, [fetchRankings]);

  // Reason: Listen for the "rankingRefreshNeeded" custom event dispatched when a
  // position is closed. This triggers an immediate re-fetch so the user sees
  // updated win rate / PnL without waiting for the next 15-second poll.
  useEffect(() => {
    const handleRefresh = () => {
      fetchRankings();
    };
    window.addEventListener("rankingRefreshNeeded", handleRefresh);
    return () => window.removeEventListener("rankingRefreshNeeded", handleRefresh);
  }, [fetchRankings]);

  // Get ranking method label
  const getRankingLabel = () => {
    switch (rankingMethod) {
      case "pnl":
        return "P&L";
      case "roi":
        return "ROI";
      case "total_capital":
        return "Equity";
      case "win_rate":
        return "Win %";
      case "total_wins":
        return "Wins";
      case "profit_factor":
        return "PF";
      default:
        return "P&L";
    }
  };

  // Format display value based on ranking method
  const formatDisplayValue = (value: number) => {
    switch (rankingMethod) {
      case "roi":
      case "win_rate":
        return `${value >= 0 ? "+" : ""}${value.toFixed(1)}%`;
      case "total_wins":
        return value.toString();
      case "profit_factor":
        return value.toFixed(2);
      default:
        return `${value >= 0 ? "+" : "-"}${currSymbol}${Math.abs(value).toFixed(0)}`;
    }
  };

  // Format distance to first
  const formatDistance = (value: number) => {
    if (value === 0) return null;
    switch (rankingMethod) {
      case "roi":
      case "win_rate":
        return `${value.toFixed(1)}%`;
      case "total_wins":
        return value.toString();
      default:
        return `${currSymbol}${Math.abs(value).toFixed(0)}`;
    }
  };

  // Get rank display with gaming flair
  const getRankDisplay = (rank: number, isDisqualified: boolean) => {
    if (isDisqualified) {
      return <Skull className="w-4 h-4 text-red-500" />;
    }
    switch (rank) {
      case 1:
        return <span className="text-lg">≡ƒÑç</span>;
      case 2:
        return <span className="text-lg">≡ƒÑê</span>;
      case 3:
        return <span className="text-lg">≡ƒÑë</span>;
      default:
        return (
          <span className="text-xs font-bold text-purple-300">#{rank}</span>
        );
    }
  };

  if (loading) {
    return (
      <div className="bg-gradient-to-br from-[#1a1a2e] to-[#16213e] rounded-2xl border-2 border-purple-500/50 p-6">
        <div className="flex items-center justify-center gap-2">
          <Loader2 className="w-5 h-5 text-purple-400 animate-spin" />
          <span className="text-purple-300 text-sm">Loading rankings...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-gradient-to-br from-[#1a1a2e] to-[#16213e] rounded-2xl border-2 border-purple-500/50 p-4">
        <div className="text-center text-gray-400 text-sm">{error}</div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "bg-gradient-to-br from-[#1a1a2e] to-[#16213e] rounded-2xl border-2 border-purple-500/50 overflow-hidden",
        className,
      )}
    >
      {/* Gaming Header */}
      <div className="bg-gradient-to-r from-yellow-600 via-orange-500 to-red-500 p-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Crown className="w-5 h-5 text-white drop-shadow-lg" />
          <span className="text-white font-bold text-lg">Leaderboard</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="size-2 bg-green-400 rounded-full animate-pulse shadow-lg shadow-green-400/50" />
          <span className="text-white/90 text-xs font-medium">
            {totalParticipants} warriors
          </span>
        </div>
      </div>

      {/* Ranking Method Badge */}
      <div className="px-4 pt-3 pb-2">
        <div className="flex items-center justify-between">
          <span className="text-[10px] text-purple-400 uppercase tracking-wider font-medium">
            ΓÜö∩╕Å Ranked by {getRankingLabel()}
          </span>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-1 px-4 py-2 bg-purple-500/10 text-[10px] font-bold text-purple-300 uppercase tracking-wider">
        <div className="col-span-1">#</div>
        <div className="col-span-4">Warrior</div>
        <div className="col-span-2 text-right">{getRankingLabel()}</div>
        <div className="col-span-3 text-right">≡ƒÆ░ Reward</div>
        <div className="col-span-2 text-right">≡ƒÄ» Gap</div>
      </div>

      {/* Rankings List */}
      <div className="max-h-[250px] overflow-y-auto scrollbar-thin scrollbar-thumb-purple-500/50 scrollbar-track-transparent">
        {rankings.map((entry, index) => {
          const isCurrentUser = entry.userId === userId;
          const displayValue = entry.displayValue ?? entry.profitPercent;
          const distanceStr = formatDistance(entry.distanceToFirst);

          // Separator for user outside top 10
          if (entry.isSeparator && index > 0) {
            return (
              <div key={`sep-${entry.userId}`}>
                <div className="flex items-center justify-center py-1 my-1">
                  <div className="flex items-center gap-2 text-purple-500">
                    <span className="text-xs">ΓÇó ΓÇó ΓÇó</span>
                  </div>
                </div>
                <RankingRow
                  entry={entry}
                  isCurrentUser={true}
                  displayValue={displayValue}
                  distanceStr={distanceStr}
                  formatDisplayValue={formatDisplayValue}
                  getRankDisplay={getRankDisplay}
                  currSymbol={currSymbol}
                  unit={unit}
                />
              </div>
            );
          }

          return (
            <RankingRow
              key={entry.userId}
              entry={entry}
              isCurrentUser={isCurrentUser}
              displayValue={displayValue}
              distanceStr={distanceStr}
              formatDisplayValue={formatDisplayValue}
              getRankDisplay={getRankDisplay}
              currSymbol={currSymbol}
              unit={unit}
            />
          );
        })}
      </div>

      {/* Your Position Summary */}
      {userRank && (
        <div className="px-4 py-3 border-t-2 border-purple-500/30 bg-purple-500/10">
          <div className="flex items-center justify-between">
            <span className="text-purple-300 text-sm flex items-center gap-2">
              <Swords className="w-4 h-4" />
              Your Position:
            </span>
            <span
              className={cn(
                "font-black text-lg",
                userRank <= 3 ? "text-yellow-400" : "text-purple-300",
              )}
            >
              #{userRank} of {totalParticipants}
            </span>
          </div>
        </div>
      )}

      {/* Prize Pool - Gaming Style */}
      {prizePool > 0 && (
        <div className="p-3 bg-gradient-to-r from-yellow-500/20 via-orange-500/20 to-red-500/20 border-t-2 border-yellow-500/30">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Image
                src="/game-icons/treasure.png"
                alt="Prize"
                width={24}
                height={24}
                className="drop-shadow-lg"
              />
              <span className="text-yellow-300 font-bold">Prize Pool</span>
            </div>
            <span className="text-2xl font-black text-yellow-400 drop-shadow-lg">
              {formatVolts(prizePool, { unit })}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

// Ranking Row Component
function RankingRow({
  entry,
  isCurrentUser,
  displayValue,
  distanceStr,
  formatDisplayValue,
  getRankDisplay,
  currSymbol,
  unit,
}: {
  entry: RankingEntry;
  isCurrentUser: boolean;
  displayValue: number;
  distanceStr: string | null;
  formatDisplayValue: (value: number) => string;
  getRankDisplay: (rank: number, isDisqualified: boolean) => React.ReactNode;
  currSymbol: string;
  unit?: string;
}) {
  return (
    <div
      className={cn(
        "grid grid-cols-12 gap-1 items-center px-4 py-2.5 transition-all border-b border-purple-500/10",
        isCurrentUser
          ? "bg-gradient-to-r from-purple-500/30 to-pink-500/20 border-l-4 border-l-purple-500"
          : entry.rank <= 3 && !entry.isDisqualified
            ? "bg-gradient-to-r from-yellow-500/10 to-orange-500/5"
            : "hover:bg-purple-500/10",
        entry.isDisqualified && "opacity-60",
      )}
    >
      {/* Rank */}
      <div className="col-span-1 flex items-center justify-center">
        {getRankDisplay(entry.rank, entry.isDisqualified)}
      </div>

      {/* Username */}
      <div className="col-span-4 min-w-0">
        <p
          className={cn(
            "text-sm font-bold truncate",
            isCurrentUser ? "text-purple-300" : "text-white",
            entry.isDisqualified && "text-red-400 line-through",
          )}
        >
          {isCurrentUser ? "ΓÜö∩╕Å You" : entry.username}
        </p>
      </div>

      {/* Display Value */}
      <div className="col-span-2 text-right">
        <span
          className={cn(
            "text-sm font-bold tabular-nums",
            displayValue > 0
              ? "text-green-400"
              : displayValue < 0
                ? "text-red-400"
                : "text-gray-400",
          )}
        >
          {formatDisplayValue(displayValue)}
        </span>
      </div>

      {/* Potential Reward */}
      <div className="col-span-3 text-right">
        {entry.potentialReward > 0 ? (
          <span className="text-sm font-bold text-yellow-400 tabular-nums">
            {formatVolts(entry.potentialReward, { unit })}
          </span>
        ) : (
          <span className="text-xs text-gray-600">ΓÇö</span>
        )}
      </div>

      {/* Distance to 1st */}
      <div className="col-span-2 text-right">
        {entry.rank === 1 ? (
          <span className="text-lg">≡ƒææ</span>
        ) : entry.isDisqualified ? (
          <span className="text-xs text-gray-600">≡ƒÆÇ</span>
        ) : distanceStr ? (
          <span className="text-xs text-orange-400 tabular-nums font-medium">
            {distanceStr}
          </span>
        ) : (
          <span className="text-xs text-gray-600">ΓÇö</span>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import {
  Trophy,
  Target,
  Loader2,
  Skull,
  MoreHorizontal,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useAppSettings } from "@/contexts/AppSettingsContext";
import { formatVolts } from "@/lib/utils/format-volts";

interface RankingEntry {
  rank: number;
  userId: string;
  username: string;
  profitPercent: number;
  displayValue: number;
  liveEquity: number;
  potentialReward: number;
  distanceToFirst: number;
  isDisqualified: boolean;
  status: string;
  rankingMethod?: string;
  isSeparator?: boolean;
}

interface LiveRankingPanelProps {
  competitionId: string;
  userId: string;
  className?: string;
}

export default function LiveRankingPanel({
  competitionId,
  userId,
  className,
}: LiveRankingPanelProps) {
  const { settings } = useAppSettings();
  // Two different units share this panel and only one of them is credits.
  //
  // `currSymbol` prefixes the ranking metric and the distance to first, which are the player's
  // simulated TRADING capital - not credits, and not something this task decides the unit of.
  // The prize pool and the potential reward are credits, debited from and paid into the credit
  // wallet, so they are written in Volts. Reason: giving both the same symbol is what made the
  // two look like one quantity.
  const currSymbol = settings?.currency?.symbol || "Γé¼";
  const unit = settings?.credits?.name;
  const [rankings, setRankings] = useState<RankingEntry[]>([]);
  const [userRank, setUserRank] = useState<number | null>(null);
  const [totalParticipants, setTotalParticipants] = useState(0);
  const [prizePool, setPrizePool] = useState(0);
  const [rankingMethod, setRankingMethod] = useState<string>("pnl");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchRankings = useCallback(async () => {
    try {
      const response = await fetch(
        `/api/competitions/${competitionId}/live-ranking`,
      );
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Failed to fetch rankings");
      }

      setRankings(data.rankings || []);
      setUserRank(data.userRank);
      setTotalParticipants(data.totalParticipants || 0);
      setPrizePool(data.prizePool || 0);
      setRankingMethod(data.rankingMethod || "pnl");
      setError(null);

      // Reason: Fire a custom event when the API detects "last man standing"
      // and the current user is that player, so the trade page can show a popup.
      if (data.isLastManStanding && data.lastManUserId === userId) {
        window.dispatchEvent(
          new CustomEvent("lastManStanding", {
            detail: { competitionId, prizePool: data.prizePool || 0 },
          }),
        );
      }
    } catch (err) {
      console.error("Error fetching live rankings:", err);
      setError(err instanceof Error ? err.message : "Failed to load");
    } finally {
      setLoading(false);
    }
  }, [competitionId, userId]);

  // Initial fetch and polling
  useEffect(() => {
    fetchRankings();

    // Poll every 15 seconds for live updates (reduced from 5s to lower server load)
    const interval = setInterval(fetchRankings, 15000);

    return () => clearInterval(interval);
  }, [fetchRankings]);

  // Reason: Listen for the "rankingRefreshNeeded" custom event dispatched when a
  // position is closed. This triggers an immediate re-fetch so the user sees
  // updated win rate / PnL without waiting for the next 15-second poll.
  useEffect(() => {
    const handleRefresh = () => {
      fetchRankings();
    };
    window.addEventListener("rankingRefreshNeeded", handleRefresh);
    return () => window.removeEventListener("rankingRefreshNeeded", handleRefresh);
  }, [fetchRankings]);

  const getRankIcon = (rank: number, isDisqualified: boolean) => {
    if (isDisqualified) {
      return <Skull className="h-4 w-4 text-red-500" />;
    }

    switch (rank) {
      case 1:
        return <Trophy className="h-4 w-4 text-yellow-400" />;
      case 2:
        return <Trophy className="h-4 w-4 text-gray-400" />;
      case 3:
        return <Trophy className="h-4 w-4 text-orange-500" />;
      default:
        return (
          <span className="w-4 h-4 rounded-full bg-dark-500 flex items-center justify-center text-[10px] text-gray-400 font-bold">
            {rank}
          </span>
        );
    }
  };

  const getRankBgColor = (
    rank: number,
    isCurrentUser: boolean,
    isDisqualified: boolean,
  ) => {
    if (isDisqualified) return "bg-red-500/5 border-red-500/20";
    if (isCurrentUser) return "bg-primary/10 border-primary/30";
    if (rank === 1) return "bg-yellow-500/5 border-yellow-500/20";
    if (rank === 2) return "bg-gray-500/5 border-gray-500/20";
    if (rank === 3) return "bg-orange-500/5 border-orange-500/20";
    return "bg-dark-400/30 border-dark-500/30";
  };

  if (loading) {
    return (
      <div className={cn("space-y-3", className)}>
        <div className="flex items-center justify-center py-8">
          <Loader2 className="h-5 w-5 animate-spin text-primary" />
          <span className="ml-2 text-sm text-gray-400">
            Loading rankings...
          </span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={cn("space-y-3", className)}>
        <div className="text-center py-6">
          <p className="text-xs text-red-400">{error}</p>
          <button
            onClick={fetchRankings}
            className="mt-2 text-xs text-primary hover:underline"
          >
            Try again
          </button>
        </div>
      </div>
    );
  }

  if (rankings.length === 0) {
    return (
      <div className={cn("space-y-3", className)}>
        <div className="text-center py-6">
          <Trophy className="h-8 w-8 text-gray-600 mx-auto mb-2" />
          <p className="text-xs text-gray-500">No participants yet</p>
        </div>
      </div>
    );
  }

  // Get ranking method label
  const getRankingLabel = () => {
    switch (rankingMethod) {
      case "pnl":
        return "P&L";
      case "roi":
        return "ROI";
      case "total_capital":
        return "Equity";
      case "win_rate":
        return "Win %";
      case "total_wins":
        return "Wins";
      case "profit_factor":
        return "PF";
      default:
        return "P&L";
    }
  };

  // Format display value based on ranking method
  const formatDisplayValue = (value: number) => {
    switch (rankingMethod) {
      case "roi":
      case "win_rate":
        return `${value >= 0 ? "+" : ""}${value.toFixed(2)}%`;
      case "total_wins":
        return value.toString();
      case "profit_factor":
        return value.toFixed(2);
      default: // pnl, total_capital
        return `${value >= 0 ? "+" : "-"}${currSymbol}${Math.abs(value).toFixed(2)}`;
    }
  };

  // Format distance to first based on ranking method
  const formatDistance = (value: number) => {
    if (value === 0) return null;
    switch (rankingMethod) {
      case "roi":
      case "win_rate":
        return `${value.toFixed(1)}%`;
      case "total_wins":
        return value.toString();
      case "profit_factor":
        return value.toFixed(2);
      default: // pnl, total_capital
        return `${currSymbol}${Math.abs(value).toFixed(0)}`;
    }
  };

  return (
    <div className={cn("space-y-3", className)}>
      {/* Header - just show traders count and ranking type */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <div className="size-1.5 bg-green-400 rounded-full animate-pulse" />
          <span className="text-[10px] text-gray-400">
            {totalParticipants} traders
          </span>
          <span className="text-[10px] text-gray-600">ΓÇó</span>
          <span className="text-[10px] text-primary/80">
            Ranked by {getRankingLabel()}
          </span>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-1 px-2 text-[10px] font-semibold text-gray-500 uppercase tracking-wider">
        <div className="col-span-1">#</div>
        <div className="col-span-4">Trader</div>
        <div className="col-span-2 text-right">{getRankingLabel()}</div>
        <div className="col-span-3 text-right">Reward</div>
        <div className="col-span-2 text-right">To 1st</div>
      </div>

      {/* Rankings List */}
      <div className="space-y-1.5 max-h-[280px] overflow-y-auto scrollbar-thin scrollbar-thumb-dark-500 scrollbar-track-transparent">
        {rankings.map((entry, index) => {
          const isCurrentUser = entry.userId === userId;

          // Show separator before user's out-of-top position
          if (entry.isSeparator && index > 0) {
            return (
              <div key={`sep-${entry.userId}`}>
                <div className="flex items-center justify-center py-1 my-1">
                  <MoreHorizontal className="h-4 w-4 text-gray-600" />
                </div>
                <RankingRow
                  entry={entry}
                  isCurrentUser={true}
                  getRankIcon={getRankIcon}
                  getRankBgColor={getRankBgColor}
                  formatDisplayValue={formatDisplayValue}
                  formatDistance={formatDistance}
                  currSymbol={currSymbol}
                  unit={unit}
                />
              </div>
            );
          }

          return (
            <RankingRow
              key={entry.userId}
              entry={entry}
              isCurrentUser={isCurrentUser}
              getRankIcon={getRankIcon}
              getRankBgColor={getRankBgColor}
              formatDisplayValue={formatDisplayValue}
              formatDistance={formatDistance}
              currSymbol={currSymbol}
              unit={unit}
            />
          );
        })}
      </div>

      {/* Your Position Summary (if in rankings) */}
      {userRank && (
        <div className="pt-2 mt-2 border-t border-dark-500/50">
          <div className="flex items-center justify-between text-xs">
            <span className="text-gray-400">Your Position:</span>
            <span
              className={cn(
                "font-bold",
                userRank <= 3 ? "text-yellow-400" : "text-gray-300",
              )}
            >
              #{userRank} of {totalParticipants}
            </span>
          </div>
        </div>
      )}

      {/* Prize Pool Info */}
      {prizePool > 0 && (
        <div className="bg-gradient-to-r from-yellow-500/10 to-orange-500/10 rounded-lg p-2.5 border border-yellow-500/20">
          <div className="flex items-center justify-between text-xs">
            <span className="text-yellow-400/80 flex items-center gap-1">
              <Trophy className="h-3 w-3" />
              Prize Pool
            </span>
            <span className="font-bold text-yellow-400">
              {formatVolts(prizePool, { unit })}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

// Separate row component for cleaner rendering
function RankingRow({
  entry,
  isCurrentUser,
  getRankIcon,
  getRankBgColor,
  formatDisplayValue,
  formatDistance,
  currSymbol,
  unit,
}: {
  entry: RankingEntry;
  isCurrentUser: boolean;
  getRankIcon: (rank: number, isDisqualified: boolean) => React.ReactNode;
  getRankBgColor: (
    rank: number,
    isCurrentUser: boolean,
    isDisqualified: boolean,
  ) => string;
  formatDisplayValue: (value: number) => string;
  formatDistance: (value: number) => string | null;
  currSymbol: string;
  unit?: string;
}) {
  const displayValue = entry.displayValue ?? entry.profitPercent;
  const distanceStr = formatDistance(entry.distanceToFirst);

  return (
    <div
      className={cn(
        "grid grid-cols-12 gap-1 items-center px-2 py-2 rounded-lg border transition-all",
        getRankBgColor(entry.rank, isCurrentUser, entry.isDisqualified),
        isCurrentUser && "ring-1 ring-primary/50",
      )}
    >
      {/* Rank */}
      <div className="col-span-1 flex items-center">
        {getRankIcon(entry.rank, entry.isDisqualified)}
      </div>

      {/* Username */}
      <div className="col-span-4 min-w-0">
        <p
          className={cn(
            "text-xs font-medium truncate",
            isCurrentUser ? "text-primary" : "text-gray-200",
            entry.isDisqualified && "text-red-400 line-through",
          )}
        >
          {isCurrentUser ? "You" : entry.username}
        </p>
      </div>

      {/* Display Value (P&L, ROI, etc based on ranking method) */}
      <div className="col-span-2 text-right">
        <span
          className={cn(
            "text-xs font-bold tabular-nums",
            displayValue > 0
              ? "text-green-400"
              : displayValue < 0
                ? "text-red-400"
                : "text-gray-400",
          )}
        >
          {formatDisplayValue(displayValue)}
        </span>
      </div>

      {/* Potential Reward */}
      <div className="col-span-3 text-right">
        {entry.potentialReward > 0 ? (
          <span className="text-xs font-bold text-yellow-400 tabular-nums">
            {formatVolts(entry.potentialReward, { unit })}
          </span>
        ) : (
          <span className="text-xs text-gray-600">ΓÇö</span>
        )}
      </div>

      {/* Distance to 1st */}
      <div className="col-span-2 text-right">
        {entry.rank === 1 ? (
          <span className="text-xs text-yellow-400">≡ƒÅå</span>
        ) : entry.isDisqualified ? (
          <span className="text-xs text-gray-600">ΓÇö</span>
        ) : distanceStr ? (
          <span className="text-xs text-gray-400 tabular-nums flex items-center justify-end gap-0.5">
            <Target className="h-3 w-3 text-gray-500" />
            {distanceStr}
          </span>
        ) : (
          <span className="text-xs text-gray-600">ΓÇö</span>
        )}
      </div>
    </div>
  );
}

import Notification from "@/database/models/notification.model";
import NotificationTemplate, {
  NotificationType,
  NotificationCategory,
} from "@/database/models/notification-template.model";
import { connectToDatabase } from "@/database/mongoose";
// Reason: a competition prize is credits. These three notifications told a winner they had won
// a number of euros, which is the only place the wrong unit reached a player by email as well
// as on screen. The default unit applies - see the note in the module about why a server-composed
// string does not read the operator's configured name.
import { formatVolts } from "@/lib/utils/format-volts";

export interface NotificationData {
  userId: string;
  type: NotificationType;
  metadata?: Record<string, any>;
  adminId?: string;
  adminEmail?: string;
}

export interface SendOptions {
  userId: string;
  templateId: string;
  variables?: Record<string, any>;
  adminId?: string;
  adminEmail?: string;
}

export interface GetNotificationsOptions {
  limit?: number;
  offset?: number;
  category?: NotificationCategory;
  unreadOnly?: boolean;
}

/**
 * Replace template variables with actual values
 */
function replaceVariables(
  text: string,
  variables: Record<string, any>,
): string {
  return text.replace(/\{\{(\w+)\}\}/g, (match, key) => {
    return variables[key] !== undefined ? String(variables[key]) : match;
  });
}

/**
 * Notification Service Class - provides all notification functionality
 */
class NotificationService {
  /**
   * Send a notification using a template
   */
  async send(options: SendOptions): Promise<any> {
    try {
      await connectToDatabase();

      const template = await NotificationTemplate.findOne({
        templateId: options.templateId,
        isEnabled: true,
      });

      if (!template) {
        console.warn(
          `Notification template '${options.templateId}' not found or disabled`,
        );
        return null;
      }

      const variables = options.variables || {};
      const title = replaceVariables(template.title, variables);
      const message = replaceVariables(template.message, variables);
      const actionUrl = template.actionUrl
        ? replaceVariables(template.actionUrl, variables)
        : undefined;

      const notification = await Notification.create({
        userId: options.userId,
        templateId: template.templateId,
        title,
        message,
        icon: template.icon,
        category: template.category,
        type: template.type,
        priority: template.priority,
        color: template.color,
        actionUrl,
        actionText: template.actionText,
        isRead: false,
        metadata: variables,
        sentBy: options.adminId
          ? {
              adminId: options.adminId,
              adminEmail: options.adminEmail,
            }
          : undefined,
        isInstant: false,
      });

      return notification;
    } catch (error) {
      console.error("Error sending notification:", error);
      return null;
    }
  }

  /**
   * Create a custom notification directly (without template)
   */
  async createCustom(data: {
    userId: string;
    type: string;
    title: string;
    message: string;
    icon?: string;
    category?: string;
    priority?: string;
    color?: string;
    actionUrl?: string;
    actionText?: string;
    metadata?: Record<string, any>;
  }): Promise<any> {
    try {
      await connectToDatabase();

      const notification = await Notification.create({
        userId: data.userId,
        templateId: `custom_${data.type}`,
        title: data.title,
        message: data.message,
        icon: data.icon || "bell",
        category: data.category || "system",
        type: data.type,
        priority: data.priority || "normal",
        color: data.color || "blue",
        actionUrl: data.actionUrl,
        actionText: data.actionText,
        isRead: false,
        metadata: data.metadata || {},
        isInstant: true,
      });

      return notification;
    } catch (error) {
      console.error("Error creating custom notification:", error);
      return null;
    }
  }

  /**
   * Get user's notifications
   */
  async getUserNotifications(
    userId: string,
    options: GetNotificationsOptions = {},
  ) {
    await connectToDatabase();

    const { limit = 50, offset = 0, category, unreadOnly } = options;

    const query: any = { userId };
    if (category) query.category = category;
    if (unreadOnly) query.isRead = false;

    return Notification.find(query)
      .sort({ createdAt: -1 })
      .skip(offset)
      .limit(limit)
      .lean();
  }

  /**
   * Get unread notification count
   */
  async getUnreadCount(userId: string): Promise<number> {
    await connectToDatabase();
    return Notification.countDocuments({ userId, isRead: false });
  }

  /**
   * Mark a single notification as read
   */
  async markAsRead(notificationId: string, userId: string): Promise<boolean> {
    await connectToDatabase();

    const result = await Notification.findOneAndUpdate(
      { _id: notificationId, userId },
      { isRead: true, readAt: new Date() },
    );

    return !!result;
  }

  /**
   * Mark all notifications as read
   */
  async markAllAsRead(userId: string): Promise<number> {
    await connectToDatabase();

    const result = await Notification.updateMany(
      { userId, isRead: false },
      { isRead: true, readAt: new Date() },
    );

    return result.modifiedCount;
  }

  /**
   * Clear all notifications
   */
  async clearAllNotifications(userId: string): Promise<number> {
    await connectToDatabase();

    const result = await Notification.deleteMany({ userId });
    return result.deletedCount;
  }

  /**
   * Delete a single notification
   */
  async deleteNotification(
    notificationId: string,
    userId: string,
  ): Promise<boolean> {
    await connectToDatabase();

    const result = await Notification.findOneAndDelete({
      _id: notificationId,
      userId,
    });

    return !!result;
  }

  /**
   * Send notification by type (for KYC, trading events, etc.)
   */
  async sendByType(data: NotificationData): Promise<boolean> {
    const result = await this.send({
      userId: data.userId,
      templateId: data.type,
      variables: data.metadata,
      adminId: data.adminId,
      adminEmail: data.adminEmail,
    });
    return !!result;
  }

